USE plan_remediacion_db;

INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2001-0554', 'Función telrcv de telnetd basada en BSD para la ejecución remota de comandos.', 'Crítico', 10.0, 'El servidor telnet remoto puede ser vulnerable a un ataque de desbordamiento de búfer.', 'El servidor Telnet no devuelve el número esperado de respuestas al recibir una larga secuencia de comandos ''Are You There''. Esto probablemente significa que se produce un desbordamiento en uno de sus búferes internos y el servidor falla. Esto podría dar lugar a la ejecución de código arbitrario.', 'Desactive el servicio telnet, por ejemplo, comentando la línea ''telnet'' en /etc/inetd.conf.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2017-3881', 'Manejo de opciones de Telnet del protocolo de administración de clústeres de Cisco IOS (cisco-sa-20170317-cmp) (verificación destructiva)', 'Crítico', 10.0, 'El dispositivo remoto se ve afectado por una vulnerabilidad de ejecución remota de código.', 'El dispositivo remoto se ve afectado por una vulnerabilidad de ejecución remota de código en el subsistema del Protocolo de Gestión de Clústeres (CMP) debido a un manejo incorrecto de las opciones Telnet específicas de CMP. Un atacante remoto no autenticado puede explotar esta vulnerabilidad estableciendo una sesión Telnet con opciones Telnet específicas de CMP mal formadas para ejecutar código arbitrario.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCvd48893. Como solución alternativa, desactive el protocolo Telnet para las conexiones entrantes.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2025-22224, CVE-2025-22225, CVE-2025-22226', 'Múltiples vulnerabilidades en VMware ESXi 7.0 / 8.0 (VMSA-2025-0004)', 'Crítico', 7.2, 'El host remoto VMware ESXi se ve afectado por múltiples vulnerabilidades.', 'La versión de VMware ESXi instalada en el host remoto es 7.0 anterior a 7.0 Update 3s, 8.0 Update 2 anterior a 8.0 Update 2d o 8.0 Update 3 anterior a 8.0 Update 3d. Por lo tanto, se ve afectada por múltiples vulnerabilidades, como se indica en el aviso VMSA-2025-0004:

VMware ESXi y Workstation presentan una vulnerabilidad TOCTOU (Time-of-Check Time-of-Use) que provoca una escritura fuera de los límites de la memoria. Un atacante con privilegios de administrador local en una máquina virtual podría explotar esta vulnerabilidad para ejecutar código como el proceso VMX de la máquina virtual que se ejecuta en el host. (CVE-2025-22224)

VMware ESXi presenta una vulnerabilidad de escritura arbitraria. Un atacante con privilegios dentro del proceso VMX podría provocar una escritura arbitraria en el kernel, lo que permitiría escapar del entorno aislado (sandbox). (CVE-2025-22225)

VMware ESXi, Workstation y Fusion presentan una vulnerabilidad de divulgación de información debido a una lectura fuera de límites en HGFS. Un atacante con privilegios administrativos en una máquina virtual podría explotar esta vulnerabilidad para filtrar memoria del proceso vmx. (CVE-2025-22226)', 'Actualice a VMware ESXi 7.0 Update 3s, 8.0 Update 2d o 8.0 Update 3d o posterior.', 'Procedimiento / Software', NOW());
