INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2025-41236, CVE-2025-41237, CVE-2025-41238, CVE-2025-41239', 'VMware ESXi 7.x < 7.0 Actualización 3w / 8.x < 8.0 Actualización 2e / 8.0 Actualización 3 < 8.0 Actualización 3f (VMSA-2025-0013)', 'Crítico', 7.2, 'VMware ESXi se ve afectado por múltiples vulnerabilidades.', 'La versión de VMware ESXi instalada en el host remoto es 7.x anterior a la actualización 3w de la versión 7.0, 8.x anterior a la actualización 2e de la versión 8.0 o 8.0 Actualización 3 anterior a la actualización 3f de la versión 8.0. Por lo tanto, se ve afectada por múltiples vulnerabilidades, como se indica en el aviso VMSA-2025-0013:

VMware ESXi, Workstation y Fusion presentan una vulnerabilidad de desbordamiento de enteros en el adaptador de red virtual VMXNET3. (CVE-2025-41236)

VMware ESXi, Workstation y Fusion contienen una vulnerabilidad de desbordamiento negativo de enteros en VMCI (Interfaz de Comunicación de Máquinas Virtuales) que provoca una escritura fuera de los límites de la memoria. (CVE-2025-41237)

VMware ESXi, Workstation y Fusion presentan una vulnerabilidad de desbordamiento de búfer en el controlador PVSCSI (SCSI paravirtualizado) que provoca una escritura fuera de los límites de la memoria. (CVE-2025-41238)

VMware ESXi, Workstation, Fusion y VMware Tools presentan una vulnerabilidad de divulgación de información debido al uso de memoria no inicializada en vSockets. (CVE-2025-41239)', 'Actualice a VMware ESXi 7.0 Update 3w, 8.0 Update 2e o 8.0 Update 3f o posterior.', 'Procedimiento / Software', NOW());
