INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Detección de versiones no compatibles de VMware ESX / ESXi', 'Crítico', 10.0, 'El host remoto está ejecutando una versión no compatible de una aplicación de virtualización.', 'Según su versión, la instalación de VMware ESX o ESXi en el host remoto ya no es compatible.

La falta de soporte implica que el proveedor no lanzará nuevos parches de seguridad para el producto. En consecuencia, es probable que contenga vulnerabilidades de seguridad.', 'Actualice a una versión de VMware ESX / ESXi que sea compatible actualmente.', 'Procedimiento / Software', NOW());
