INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2020-3955', 'ESXi 6.5 / 6.7 XSS (VMSA-2020-0008)', 'Crítico', 4.3, 'El host remoto VMware ESXi carece de un parche de seguridad y se ve afectado por una vulnerabilidad de secuencias de comandos entre sitios (XSS).', 'El host VMware ESXi remoto es la versión 6.5 o 6.7 y se ve afectado por una vulnerabilidad de secuencias de comandos entre sitios (XSS) en los atributos de la máquina virtual debido a una validación incorrecta de la información proporcionada por el usuario antes de devolverla. Un atacante remoto autenticado con acceso para modificar las propiedades del sistema de una máquina virtual desde el sistema operativo invitado puede explotar esta vulnerabilidad insertando código HTML relacionado con scripts en las propiedades del sistema y permitiendo que un usuario visualice dichas propiedades desde el cliente del host ESXi, para ejecutar código de script arbitrario en la sesión del cliente del host ESXi del usuario.', 'Aplique el parche correspondiente según se indica en el aviso del proveedor.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2020-3955', 'ESXi 6.5 / 6.7 XSS (VMSA-2020-0008)', 'Crítico', 4.3, 'El host remoto VMware ESXi carece de un parche de seguridad y se ve afectado por una vulnerabilidad de secuencias de comandos entre sitios (XSS).', 'El host VMware ESXi remoto es la versión 6.5 o 6.7 y se ve afectado por una vulnerabilidad de secuencias de comandos entre sitios (XSS) en los atributos de la máquina virtual debido a una validación incorrecta de la información proporcionada por el usuario antes de devolverla. Un atacante remoto autenticado con acceso para modificar las propiedades del sistema de una máquina virtual desde el sistema operativo invitado puede explotar esta vulnerabilidad insertando código HTML relacionado con scripts en las propiedades del sistema y permitiendo que un usuario visualice dichas propiedades desde el cliente del host ESXi, para ejecutar código de script arbitrario en la sesión del cliente del host ESXi del usuario.', 'Aplique el parche correspondiente según se indica en el aviso del proveedor.', 'Procedimiento / Software', NOW());
