INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Detección de protocolo SSL versión 2 y 3', 'Crítico', 10.0, 'El servicio remoto cifra el tráfico utilizando un protocolo con vulnerabilidades conocidas.', 'El servicio remoto acepta conexiones cifradas mediante SSL 2.0 y/o SSL 3.0. Estas versiones de SSL se ven afectadas por varias vulnerabilidades criptográficas, entre ellas:

- Un esquema de relleno inseguro con cifrados CBC.

- Esquemas inseguros de renegociación y reanudación de sesiones.

Un atacante puede explotar estas vulnerabilidades para llevar a cabo ataques de intermediario o para descifrar las comunicaciones entre el servicio afectado y los clientes.

Aunque SSL/TLS cuenta con un mecanismo seguro para seleccionar la versión más reciente del protocolo compatible (de modo que estas versiones solo se utilicen si el cliente o el servidor no admiten ninguna mejor), muchos navegadores web implementan esta funcionalidad de forma insegura, lo que permite a un atacante degradar la conexión (como en el caso de POODLE). Por lo tanto, se recomienda deshabilitar completamente estos protocolos.

El NIST ha determinado que SSL 3.0 ya no es aceptable para comunicaciones seguras. A partir de la fecha de entrada en vigor establecida en la norma PCI DSS v3.1, ninguna versión de SSL cumplirá con la definición de "criptografía robusta" del PCI SSC.', 'Consulte la documentación de la aplicación para desactivar SSL 2.0 y 3.0.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Detección de protocolo SSL versión 2 y 3', 'Crítico', 10.0, 'El servicio remoto cifra el tráfico utilizando un protocolo con vulnerabilidades conocidas.', 'El servicio remoto acepta conexiones cifradas mediante SSL 2.0 y/o SSL 3.0. Estas versiones de SSL se ven afectadas por varias vulnerabilidades criptográficas, entre ellas:

