INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-18394', 'Openfire SSRF (CVE-2019-18394)', 'Crítico', 7.5, 'La aplicación web que se ejecuta en el servidor web remoto se ve afectada por una vulnerabilidad de falsificación de solicitudes del lado del servidor.', 'La versión de Openfire instalada en el host remoto es anterior a la 4.4.3. Por lo tanto, se ve afectada por una vulnerabilidad de falsificación de solicitud del lado del servidor en FaviconServlet.java en Ignite Realtime Openfire hasta la versión 4.4.2 permite a los atacantes enviar solicitudes HTTP GET arbitrarias.', 'Actualiza a Metabase versión 4.4.3 o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Sistema operativo Windows no compatible (remoto)', 'Crítico', 10.0, 'El sistema operativo o paquete de servicio remoto ya no es compatible.', 'La versión remota de Microsoft Windows carece de un paquete de servicio o ya no cuenta con soporte. Por lo tanto, es probable que contenga vulnerabilidades de seguridad.', 'Actualiza a un paquete de servicio o sistema operativo compatible.', 'Procedimiento / Software', NOW());
