INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Detección de versiones no compatibles de Microsoft SQL Server (verificación remota)', 'Crítico', 10.0, 'En el host remoto se está ejecutando una versión no compatible de un servidor de base de datos.', 'Según la versión que ellos mismos han indicado, la instalación de Microsoft SQL Server en el host remoto ya no es compatible.

La falta de soporte implica que el proveedor no lanzará nuevos parches de seguridad para el producto. En consecuencia, es probable que contenga vulnerabilidades de seguridad.', 'Actualice a una versión de Microsoft SQL Server que sea compatible actualmente.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Detección de versiones no compatibles de Microsoft SQL Server (verificación remota)', 'Crítico', 10.0, 'En el host remoto se está ejecutando una versión no compatible de un servidor de base de datos.', 'Según la versión que ellos mismos han indicado, la instalación de Microsoft SQL Server en el host remoto ya no es compatible.

La falta de soporte implica que el proveedor no lanzará nuevos parches de seguridad para el producto. En consecuencia, es probable que contenga vulnerabilidades de seguridad.', 'Actualice a una versión de Microsoft SQL Server que sea compatible actualmente.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Detección de versiones no compatibles de PHP', 'Crítico', 10.0, 'El host remoto contiene una versión no compatible de un lenguaje de scripting para aplicaciones web.', 'Según su versión, la instalación de PHP en el host remoto ya no es compatible.

La falta de soporte implica que el proveedor no lanzará nuevos parches de seguridad para el producto. En consecuencia, es probable que contenga vulnerabilidades de seguridad.', 'Actualiza a una versión de PHP que sea compatible actualmente.', 'Procedimiento / Software', NOW());
