INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Ubuntu Linux SEOL canónico (18.04.x)', 'Crítico', 10.0, 'En el host remoto está instalada una versión no compatible de Canonical Ubuntu Linux.', 'Según su versión, Canonical Ubuntu Linux es la 18.04.x. Por lo tanto, ya no recibe mantenimiento por parte de su proveedor.

La falta de soporte implica que el proveedor no lanzará nuevos parches de seguridad para el producto. En consecuencia, este podría contener vulnerabilidades de seguridad.', 'Actualiza a una versión de Canonical Ubuntu Linux que sea compatible actualmente.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2020-1745, CVE-2020-1938', 'Inyección de solicitudes del conector AJP de Apache Tomcat (Ghostcat)', 'Crítico', 7.5, 'Existe un conector AJP vulnerable que está escuchando en el host remoto.', 'Se ha detectado una vulnerabilidad de lectura/inclusión de archivos en el conector AJP. Un atacante remoto no autenticado podría explotar esta vulnerabilidad para leer archivos de aplicaciones web desde un servidor vulnerable. En los casos en que el servidor vulnerable permita la carga de archivos, un atacante podría cargar código malicioso de JavaServer Pages (JSP) en diversos tipos de archivos y obtener ejecución remota de código (RCE).', 'Actualice la configuración de AJP para que requiera autorización y/o actualice el servidor Tomcat a la versión 7.0.100, 8.5.51, 9.0.31 o posterior.', 'Procedimiento / Software', NOW());
