INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-8014', 'Apache Tomcat 9.0.0 < 9.0.9', 'Crítico', 7.5, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.9. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.9_security-9.

La configuración predeterminada del filtro CORS en Apache Tomcat versiones 9.0.0.M1 a 9.0.8, 8.5.0 a 8.5.31, 8.0.0.RC1 a 8.0.52 y 7.0.41 a 7.0.88 es insegura y habilita ''supportsCredentials'' para todos los orígenes. Se espera que los usuarios del filtro CORS lo hayan configurado adecuadamente para su entorno, en lugar de utilizar la configuración predeterminada. Por lo tanto, se prevé que la mayoría de los usuarios no se vean afectados por este problema. (CVE-2018-8014)', 'Actualice a la versión 9.0.9 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
