INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2024-50379, CVE-2024-54677, CVE-2024-56337', 'Múltiples vulnerabilidades en Apache Tomcat 9.0.0.M1 < 9.0.98', 'Crítico', 6.8, 'El servidor remoto Apache Tomcat se ve afectado por múltiples vulnerabilidades.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.98. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso fixed_in_apache_tomcat_9.0.98_security-9.

La vulnerabilidad de condición de carrera Time-of-check Time-of-use (TOCTOU) durante la compilación de JSP en Apache Tomcat permite la ejecución remota de código (RCE) en sistemas de archivos que no distinguen entre mayúsculas y minúsculas cuando el servlet predeterminado está habilitado para escritura (configuración no predeterminada). Este problema afecta a Apache Tomcat: versiones 11.0.0-M1 a 11.0.1, 10.1.0-M1 a 10.1.33 y 9.0.0-M1 a 9.0.97. Se recomienda a los usuarios actualizar a las versiones 11.0.2, 10.1.34 o 9.0.98, que solucionan el problema. (CVE-2024-50379)

Vulnerabilidad de condición de carrera de tiempo de verificación y tiempo de uso (TOCTOU) en Apache Tomcat. Este problema afecta a Apache Tomcat: desde la versión 11.0.0-M1 hasta la 11.0.1, desde la 10.1.0-M1 hasta la 10.1.33, y desde la versión 9.0.0.M1 hasta la 9.0.97. La mitigación para CVE-2024-50379 fue incompleta. Los usuarios que ejecutan Tomcat en un sistema de archivos que no distingue entre mayúsculas y minúsculas con la escritura del servlet predeterminado habilitada (parámetro de inicialización de solo lectura establecido en el valor no predeterminado de falso) pueden necesitar una configuración adicional para mitigar completamente CVE-2024-50379 dependiendo de la versión de Java que estén utilizando con Tomcat: - ejecutándose en Java 8 o Java 11: la propiedad del sistema sun.io.useCanonCaches debe establecerse explícitamente en falso (por defecto es verdadero) - ejecutándose en Java 17: la propiedad del sistema sun.io.useCanonCaches, si está establecida, debe establecerse en falso (por defecto es falso) - ejecutándose en Java 21 en adelante: no se requiere ninguna configuración adicional (la propiedad del sistema y la caché problemática se han eliminado) Tomcat 11.0.3, 10.1.35 y 9.0.99 en adelante incluirán comprobaciones de que sun.io.useCanonCaches esté configurado adecuadamente antes de permitir que el servlet predeterminado se habilite para escritura en un sistema de archivos que no distingue entre mayúsculas y minúsculas. Tomcat también establecerá sun.io.useCanonCaches en falso por defecto cuando pueda. (CVE-2024-56337)

Una vulnerabilidad de consumo descontrolado de recursos en la aplicación web de ejemplo proporcionada con Apache Tomcat provoca una denegación de servicio. Este problema afecta a Apache Tomcat en las versiones 11.0.0-M1 a 11.0.1, 10.1.0-M1 a 10.1.33 y 9.0.0-M1 a 9.9.97. Se recomienda a los usuarios actualizar a las versiones 11.0.2, 10.1.34 o 9.0.98, que solucionan el problema. (CVE-2024-54677)', 'Actualice a la versión 9.0.98 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2024-50379, CVE-2024-54677, CVE-2024-56337', 'Múltiples vulnerabilidades en Apache Tomcat 9.0.0.M1 < 9.0.98', 'Crítico', 6.8, 'El servidor remoto Apache Tomcat se ve afectado por múltiples vulnerabilidades.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.98. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso fixed_in_apache_tomcat_9.0.98_security-9.

La vulnerabilidad de condición de carrera Time-of-check Time-of-use (TOCTOU) durante la compilación de JSP en Apache Tomcat permite la ejecución remota de código (RCE) en sistemas de archivos que no distinguen entre mayúsculas y minúsculas cuando el servlet predeterminado está habilitado para escritura (configuración no predeterminada). Este problema afecta a Apache Tomcat: versiones 11.0.0-M1 a 11.0.1, 10.1.0-M1 a 10.1.33 y 9.0.0-M1 a 9.0.97. Se recomienda a los usuarios actualizar a las versiones 11.0.2, 10.1.34 o 9.0.98, que solucionan el problema. (CVE-2024-50379)

Vulnerabilidad de condición de carrera de tiempo de verificación y tiempo de uso (TOCTOU) en Apache Tomcat. Este problema afecta a Apache Tomcat: desde la versión 11.0.0-M1 hasta la 11.0.1, desde la 10.1.0-M1 hasta la 10.1.33, y desde la versión 9.0.0.M1 hasta la 9.0.97. La mitigación para CVE-2024-50379 fue incompleta. Los usuarios que ejecutan Tomcat en un sistema de archivos que no distingue entre mayúsculas y minúsculas con la escritura del servlet predeterminado habilitada (parámetro de inicialización de solo lectura establecido en el valor no predeterminado de falso) pueden necesitar una configuración adicional para mitigar completamente CVE-2024-50379 dependiendo de la versión de Java que estén utilizando con Tomcat: - ejecutándose en Java 8 o Java 11: la propiedad del sistema sun.io.useCanonCaches debe establecerse explícitamente en falso (por defecto es verdadero) - ejecutándose en Java 17: la propiedad del sistema sun.io.useCanonCaches, si está establecida, debe establecerse en falso (por defecto es falso) - ejecutándose en Java 21 en adelante: no se requiere ninguna configuración adicional (la propiedad del sistema y la caché problemática se han eliminado) Tomcat 11.0.3, 10.1.35 y 9.0.99 en adelante incluirán comprobaciones de que sun.io.useCanonCaches esté configurado adecuadamente antes de permitir que el servlet predeterminado se habilite para escritura en un sistema de archivos que no distingue entre mayúsculas y minúsculas. Tomcat también establecerá sun.io.useCanonCaches en falso por defecto cuando pueda. (CVE-2024-56337)

Una vulnerabilidad de consumo descontrolado de recursos en la aplicación web de ejemplo proporcionada con Apache Tomcat provoca una denegación de servicio. Este problema afecta a Apache Tomcat en las versiones 11.0.0-M1 a 11.0.1, 10.1.0-M1 a 10.1.33 y 9.0.0-M1 a 9.9.97. Se recomienda a los usuarios actualizar a las versiones 11.0.2, 10.1.34 o 9.0.98, que solucionan el problema. (CVE-2024-54677)', 'Actualice a la versión 9.0.98 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
