INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-0708', 'Microsoft RDP RCE (CVE-2019-0708) (BlueKeep) (verificación sin credenciales)', 'Crítico', 10.0, 'El host remoto se ve afectado por una vulnerabilidad de ejecución remota de código.', 'El host remoto se ve afectado por una vulnerabilidad de ejecución remota de código en el Protocolo de Escritorio Remoto (RDP). Un atacante remoto no autenticado puede explotar esta vulnerabilidad, mediante una serie de solicitudes especialmente diseñadas, para ejecutar código arbitrario.', 'Microsoft ha publicado un conjunto de parches para Windows XP, 2003, 2008, 7 y 2008 R2.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Sistema operativo Brocade Fabric no compatible', 'Crítico', 10.0, 'El servidor remoto está ejecutando un sistema operativo obsoleto.', 'Según su versión, la instalación de Fabric OS en el host remoto ya no es compatible.

La falta de soporte implica que el proveedor no lanzará nuevos parches de seguridad para el producto. En consecuencia, es probable que contenga vulnerabilidades de seguridad.', 'Actualiza a una versión de Fabric OS que sea compatible actualmente.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Sistema operativo Brocade Fabric no compatible', 'Crítico', 10.0, 'El servidor remoto está ejecutando un sistema operativo obsoleto.', 'Según su versión, la instalación de Fabric OS en el host remoto ya no es compatible.

