INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-1999-0517', 'Nombre de comunidad predeterminado del agente SNMP (público)', 'Alto', 7.5, 'Se puede adivinar el nombre de la comunidad del servidor SNMP remoto.', 'Es posible obtener el nombre de comunidad predeterminado del servidor SNMP remoto.

