INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Ataque de denegación de servicio (DoS) por agotamiento de memoria en el encabezado HTTP del servidor web', 'Alto', 7.8, 'El servidor web remoto es vulnerable al ataque de "solicitudes infinitas".', 'Era posible bloquear el servidor web enviando una solicitud HTTP ''infinita'' no válida que nunca terminaba, como por ejemplo:

GET / HTTP/1.0 Referer: XXXXXXXXXXXXXXXXXXXXXXXX ...

Un atacante puede explotar esta vulnerabilidad para provocar que su servidor web falle continuamente (si el ataque satura la memoria virtual del objetivo) o incluso ejecutar código arbitrario en su sistema (en caso de desbordamiento de búfer/montón).', 'Actualiza tu software o protégelo con un proxy inverso con filtrado.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Ataque de denegación de servicio (DoS) por agotamiento de memoria en el encabezado HTTP del servidor web', 'Alto', 7.8, 'El servidor web remoto es vulnerable al ataque de "solicitudes infinitas".', 'Era posible bloquear el servidor web enviando una solicitud HTTP ''infinita'' no válida que nunca terminaba, como por ejemplo:

