INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2001-0361, CVE-2001-0572, CVE-2001-1473', 'Recuperación de clave de sesión del protocolo SSH versión 1', 'Alto', 7.5, 'El servicio remoto ofrece un protocolo criptográfico inseguro.', 'El demonio SSH remoto admite conexiones realizadas mediante la versión 1.33 y/o 1.5 del protocolo SSH.

Estos protocolos no son completamente seguros desde el punto de vista criptográfico, por lo que no deberían utilizarse.', 'Deshabilitar la compatibilidad con la versión 1 del protocolo SSH.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2001-0361, CVE-2001-0572, CVE-2001-1473', 'Recuperación de clave de sesión del protocolo SSH versión 1', 'Alto', 7.5, 'El servicio remoto ofrece un protocolo criptográfico inseguro.', 'El demonio SSH remoto admite conexiones realizadas mediante la versión 1.33 y/o 1.5 del protocolo SSH.

Estos protocolos no son completamente seguros desde el punto de vista criptográfico, por lo que no deberían utilizarse.', 'Deshabilitar la compatibilidad con la versión 1 del protocolo SSH.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2021-22040, CVE-2021-22041, CVE-2021-22042, CVE-2021-22043, CVE-2021-22050', 'Múltiples vulnerabilidades en ESXi 6.5 / 6.7 / 7.0 (VMSA-2022-0004)', 'Alto', 6.0, 'El host remoto VMware ESXi carece de un parche de seguridad y se ve afectado por múltiples vulnerabilidades.', 'El host remoto VMware ESXi es la versión 6.5, 6.7 o 7.0 y se ve afectado por múltiples vulnerabilidades, entre las que se incluyen las siguientes:

VMware ESXi, Workstation y Fusion presentan una vulnerabilidad de uso de memoria liberada (use-after-free) en el controlador USB XHCI. Un atacante con privilegios de administrador local en una máquina virtual podría explotar esta vulnerabilidad para ejecutar código como el proceso VMX de la máquina virtual que se ejecuta en el host. (CVE-2021-22040)

VMware ESXi, Workstation y Fusion presentan una vulnerabilidad de doble acceso en el controlador USB UHCI. Un atacante con privilegios de administrador local en una máquina virtual podría explotar esta vulnerabilidad para ejecutar código como el proceso VMX de la máquina virtual que se ejecuta en el host. (CVE-2021-22041)

VMware ESXi presenta una vulnerabilidad de acceso no autorizado debido a que VMX tiene acceso a los tickets de autorización de settingsd. Un atacante con privilegios únicamente dentro del proceso VMX podría acceder al servicio settingsd que se ejecuta como un usuario con altos privilegios. (CVE-2021-22042)', 'Aplique el parche correspondiente según se indica en el aviso del proveedor.', 'Procedimiento / Software', NOW());
