INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2022-31696, CVE-2022-31699', 'Múltiples vulnerabilidades en ESXi 6.5 / 6.7 / 7.0 (VMSA-2022-0030)', 'Alto', 6.8, 'El host remoto VMware ESXi carece de un parche de seguridad y se ve afectado por múltiples vulnerabilidades.', 'El host remoto VMware ESXi es la versión 6.5, 6.7 o 7.0 y se ve afectado por múltiples vulnerabilidades, como se detalla a continuación:

- Un problema de corrupción de memoria que puede provocar una fuga del entorno aislado de ESXi. (CVE-2022-31696)

- Una vulnerabilidad de desbordamiento de búfer que puede ser explotada para revelar información. (CVE-2022-31699)', 'Aplique el parche o la solución alternativa correspondiente, tal como se indica en el aviso del proveedor.', 'Procedimiento / Software', NOW());
