INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2024-22252, CVE-2024-22253, CVE-2024-22254, CVE-2024-22255', 'Múltiples vulnerabilidades en VMware ESXi 7.0 / 8.0 (VMSA-2024-0006)', 'Alto', 6.5, 'El host remoto VMware ESXi se ve afectado por múltiples vulnerabilidades.', 'La versión de VMware ESXi instalada en el host remoto es anterior a la actualización 3p de la versión 7.0, anterior a la actualización 1d de la versión 8.0 o anterior a la actualización 2b de la versión 8.0. Por lo tanto, se ve afectada por múltiples vulnerabilidades, como se indica en el aviso VMSA-2024-0006:

VMware ESXi, Workstation y Fusion presentan una vulnerabilidad de uso de memoria liberada en el controlador USB XHCI. (CVE-2024-22252)

VMware ESXi, Workstation y Fusion presentan una vulnerabilidad de uso de memoria liberada en el controlador USB UHCI. (CVE-2024-22253)

- VMware ESXi contiene una vulnerabilidad de escritura fuera de límites. (CVE-2024-22254)

- VMware ESXi, Workstation y Fusion contienen una vulnerabilidad de divulgación de información en el controlador USB UHCI.

(CVE-2024-22255)', 'Actualice a VMware ESXi 7.0 Update 3p, 8.0 Update 1d o 8.0 Update 2b o posterior.', 'Procedimiento / Software', NOW());
