INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'NFS comparte información legible para todo el mundo', 'Alto', 5.0, 'El servidor NFS remoto exporta recursos compartidos legibles por todos los usuarios.', 'El servidor NFS remoto está exportando uno o más recursos compartidos sin restringir el acceso (en función del nombre de host, la dirección IP o el rango de direcciones IP).', 'Establezca las restricciones adecuadas para todos los recursos compartidos de NFS.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-6974', 'Vulnerabilidad de lectura fuera de límites en ESXi 6.0 / 6.5 / 6.7 (VMSA-2018-0026) (Verificación remota)', 'Alto', 7.2, 'El host remoto VMware ESXi carece de un parche de seguridad y se ve afectado por una vulnerabilidad de lectura fuera de los límites.', 'El host remoto VMware ESXi es de la versión 6.0, 6.5 o 6.7 y carece de un parche de seguridad. Por lo tanto, es vulnerable a una vulnerabilidad de lectura fuera de límites en dispositivos SVGA. Un atacante con acceso al sistema invitado podría ejecutar código en el sistema host aprovechando esta vulnerabilidad.', 'Aplique el parche correspondiente según se indica en el aviso del proveedor.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-6974', 'Vulnerabilidad de lectura fuera de límites en ESXi 6.0 / 6.5 / 6.7 (VMSA-2018-0026) (Verificación remota)', 'Alto', 7.2, 'El host remoto VMware ESXi carece de un parche de seguridad y se ve afectado por una vulnerabilidad de lectura fuera de los límites.', 'El host remoto VMware ESXi es de la versión 6.0, 6.5 o 6.7 y carece de un parche de seguridad. Por lo tanto, es vulnerable a una vulnerabilidad de lectura fuera de límites en dispositivos SVGA. Un atacante con acceso al sistema invitado podría ejecutar código en el sistema host aprovechando esta vulnerabilidad.', 'Aplique el parche correspondiente según se indica en el aviso del proveedor.', 'Procedimiento / Software', NOW());
