INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-6981, CVE-2018-6982', 'Múltiples vulnerabilidades en ESXi 6.0 / 6.5 / 6.7 (VMSA-2018-0027) (Verificación remota)', 'Alto', 7.2, 'El host remoto VMware ESXi carece de un parche de seguridad y se ve afectado por múltiples vulnerabilidades.', 'El host VMware ESXi remoto es de la versión 6.0, 6.5 o 6.7 y carece de un parche de seguridad. Por lo tanto, es vulnerable a múltiples fallos de seguridad. Aprovechando la vulnerabilidad más grave, un atacante podría ejecutar código arbitrario en el host desde el contexto de seguridad de un usuario sin privilegios en el sistema invitado.

Nota: La vulnerabilidad CVE-2018-6982 solo se aplica a las instalaciones de ESXi 6.5 y 6.7.

Las instalaciones de ESXi 6.0 no se ven afectadas.', 'Aplique el parche correspondiente según se indica en el aviso del proveedor.', 'Procedimiento / Software', NOW());
