INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2020-4004, CVE-2020-4005', 'Múltiples vulnerabilidades en ESXi 6.5 / 6.7 / 7.0 (VMSA-2020-0026)', 'Alto', 7.2, 'El host remoto VMware ESXi carece de un parche de seguridad y se ve afectado por múltiples vulnerabilidades.', 'Según el número de versión que él mismo ha declarado, el host remoto VMware ESXi es la versión 6.5, 6.7 o 7.0 y se ve afectado por múltiples vulnerabilidades.

Existe una vulnerabilidad de uso de memoria liberada en el controlador USB XHCI. Un atacante local no autenticado con privilegios de administrador local en una máquina virtual puede explotar esta vulnerabilidad para ejecutar código como el proceso VMX de la máquina virtual que se ejecuta en el host. (CVE-2020-4004)

- Existe una vulnerabilidad de escalada de privilegios en ESXi debido a la forma en que se gestionan ciertas llamadas al sistema. Un atacante local autenticado con privilegios dentro del proceso VPM puede explotar esta vulnerabilidad, en combinación con la vulnerabilidad CVE-2020-4004, para obtener privilegios elevados. (CVE-2020-4005)', 'Aplique el parche correspondiente según se indica en el aviso del proveedor.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2020-4004, CVE-2020-4005', 'Múltiples vulnerabilidades en ESXi 6.5 / 6.7 / 7.0 (VMSA-2020-0026)', 'Alto', 7.2, 'El host remoto VMware ESXi carece de un parche de seguridad y se ve afectado por múltiples vulnerabilidades.', 'Según el número de versión que él mismo ha declarado, el host remoto VMware ESXi es la versión 6.5, 6.7 o 7.0 y se ve afectado por múltiples vulnerabilidades.

