INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2016-2183', 'Compatibilidad con conjuntos de cifrado SSL de seguridad media (SWEET32)', 'Alto', 5.0, 'El servicio remoto admite el uso de cifrados SSL de seguridad media.', 'El host remoto admite el uso de cifrados SSL que ofrecen un encriptación de seguridad media. Se considera de seguridad media cualquier cifrado que utilice claves de entre 64 y 112 bits, o bien que utilice el conjunto de cifrado 3DES.

Cabe señalar que resulta considerablemente más fácil eludir el cifrado de seguridad media si el atacante se encuentra en la misma red física.', 'Reconfigure la aplicación afectada, si es posible, para evitar el uso de cifrados de seguridad media.', 'Procedimiento / Software', NOW());
