INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-1999-1196', 'Servicio de red Datos malformados Denegación de servicio remota', 'Alto', 9.0, 'El servicio remoto es potencialmente vulnerable a un ataque de denegación de servicio.', 'Al parecer, es posible provocar la caída del servicio remoto enviándole unos pocos kilobytes de datos aleatorios.

Un atacante podría aprovechar esta vulnerabilidad para provocar fallos continuos en este servicio, impidiendo su correcto funcionamiento. También podría explotarse para ejecutar código arbitrario en este servidor.', 'Actualice su software o póngase en contacto con su proveedor para informarle de esta posible vulnerabilidad.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2015-2080', 'Error de Jetty HttpParser: Divulgación de memoria remota', 'Alto', 5.0, 'El servidor web remoto se ve afectado por una vulnerabilidad de divulgación de memoria remota.', 'La instancia remota de Jetty se ve afectada por una vulnerabilidad de divulgación de memoria remota en el módulo HttpParser debido a un manejo incorrecto de caracteres no válidos en los valores de encabezado. Cuando se encuentra un carácter no válido en una solicitud HTTP, Jetty escribe una respuesta en un búfer compartido que se utilizó en una solicitud anterior. La respuesta de Jetty al cliente incluye este búfer compartido, que contiene datos potencialmente confidenciales de la solicitud anterior. Un atacante, mediante solicitudes especialmente diseñadas que contienen cadenas de caracteres no válidos de longitud variable, puede robar datos confidenciales de encabezado (por ejemplo, cookies, tokens de autenticación) o datos POST confidenciales (por ejemplo, credenciales).', 'Actualice a Jetty 9.2.9.v20150224 o posterior. Para Jetty 9.3.x, póngase en contacto con el proveedor para obtener una solución.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2015-2080', 'Error de Jetty HttpParser: Divulgación de memoria remota', 'Alto', 5.0, 'El servidor web remoto se ve afectado por una vulnerabilidad de divulgación de memoria remota.', 'La instancia remota de Jetty se ve afectada por una vulnerabilidad de divulgación de memoria remota en el módulo HttpParser debido a un manejo incorrecto de caracteres no válidos en los valores de encabezado. Cuando se encuentra un carácter no válido en una solicitud HTTP, Jetty escribe una respuesta en un búfer compartido que se utilizó en una solicitud anterior. La respuesta de Jetty al cliente incluye este búfer compartido, que contiene datos potencialmente confidenciales de la solicitud anterior. Un atacante, mediante solicitudes especialmente diseñadas que contienen cadenas de caracteres no válidos de longitud variable, puede robar datos confidenciales de encabezado (por ejemplo, cookies, tokens de autenticación) o datos POST confidenciales (por ejemplo, credenciales).', 'Actualice a Jetty 9.2.9.v20150224 o posterior. Para Jetty 9.3.x, póngase en contacto con el proveedor para obtener una solución.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2023-32315', 'Vulnerabilidad de omisión de autenticación en Openfire (CVE-2023-32315)', 'Alto', 7.8, 'El host remoto contiene una aplicación afectada por una vulnerabilidad de omisión de autenticación.', 'El host remoto ejecuta una versión de Openfire afectada por una vulnerabilidad de omisión de autenticación. Openfire es un servidor XMPP con licencia Apache de código abierto. Se descubrió que la consola de administración de Openfire, una aplicación web, era vulnerable a un ataque de recorrido de ruta a través del entorno de configuración. Esto permitía a un usuario no autenticado utilizar el entorno de configuración de Openfire, también sin autenticación, en un entorno Openfire ya configurado para acceder a páginas restringidas de la consola de administración de Openfire, reservadas para usuarios administradores. Esta vulnerabilidad afecta a todas las versiones de Openfire publicadas desde abril de 2015, a partir de la versión 3.10.0.

El problema se ha corregido en las versiones 4.7.5 y 4.6.8 de Openfire, y se incluirán mejoras adicionales en la primera versión de la rama 4.8, aún por publicar (que se espera sea la versión 4.8.0). Se recomienda a los usuarios actualizar. Si no hay una actualización de Openfire disponible para una versión específica, o si no es posible implementarla rápidamente, los usuarios pueden consultar el aviso de GitHub (GHSA-gw42-f939-fhvm) para obtener consejos sobre cómo solucionarlo.', 'Actualice a la versión 4.6.8, 4.7.5, 4.8.0 o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2023-32315', 'Openfire 3.10 < 4.6.8 / 4.7 < 4.7.5 Omisión de autenticación', 'Alto', 7.8, 'El host remoto contiene una aplicación afectada por una vulnerabilidad de omisión de autenticación.', 'El host remoto ejecuta una versión de Openfire afectada por una vulnerabilidad de omisión de autenticación. Openfire es un servidor XMPP con licencia Apache de código abierto. Se descubrió que la consola de administración de Openfire, una aplicación web, era vulnerable a un ataque de recorrido de ruta a través del entorno de configuración. Esto permitía a un usuario no autenticado utilizar el entorno de configuración de Openfire, también sin autenticación, en un entorno Openfire ya configurado para acceder a páginas restringidas de la consola de administración de Openfire, reservadas para usuarios administradores. Esta vulnerabilidad afecta a todas las versiones de Openfire publicadas desde abril de 2015, a partir de la versión 3.10.0.

El problema se ha corregido en las versiones 4.7.5 y 4.6.8 de Openfire, y se incluirán mejoras adicionales en la primera versión de la rama 4.8, aún por publicar (que se espera sea la versión 4.8.0). Se recomienda a los usuarios actualizar. Si no hay una actualización de Openfire disponible para una versión específica, o si no es posible implementarla rápidamente, los usuarios pueden consultar el aviso de GitHub (GHSA-gw42-f939-fhvm) para obtener consejos sobre cómo solucionarlo.', 'Actualice a la versión 4.6.8, 4.7.5, 4.8.0 o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2017-9805', 'Plugin REST de Apache Struts 2 XStream Deserialización de solicitudes XML RCE', 'Alto', 6.8, 'El servidor web remoto contiene una aplicación web que utiliza un framework Java afectado por una vulnerabilidad de ejecución remota de código.', 'La aplicación web remota parece utilizar el framework web Apache Struts 2. Existe una vulnerabilidad de ejecución remota de código en el complemento REST, que utiliza XStreamHandler para deserializar de forma insegura la entrada proporcionada por el usuario en las solicitudes XML. Un atacante remoto no autenticado puede explotar esta vulnerabilidad, mediante una solicitud XML especialmente diseñada, para ejecutar código arbitrario.

Tenga en cuenta que este complemento solo informa sobre la primera instancia vulnerable de una aplicación Struts 2.', 'Actualice a Apache Struts versión 2.3.34 o 2.5.13 o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2017-9805', 'Plugin REST de Apache Struts 2 XStream Deserialización de solicitudes XML RCE', 'Alto', 6.8, 'El servidor web remoto contiene una aplicación web que utiliza un framework Java afectado por una vulnerabilidad de ejecución remota de código.', 'La aplicación web remota parece utilizar el framework web Apache Struts 2. Existe una vulnerabilidad de ejecución remota de código en el complemento REST, que utiliza XStreamHandler para deserializar de forma insegura la entrada proporcionada por el usuario en las solicitudes XML. Un atacante remoto no autenticado puede explotar esta vulnerabilidad, mediante una solicitud XML especialmente diseñada, para ejecutar código arbitrario.

Tenga en cuenta que este complemento solo informa sobre la primera instancia vulnerable de una aplicación Struts 2.', 'Actualice a Apache Struts versión 2.3.34 o 2.5.13 o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2009-3291, CVE-2009-3292, CVE-2009-3293, CVE-2009-3294, CVE-2009-4018, CVE-2009-5016', 'PHP < 5.2.11 Múltiples vulnerabilidades', 'Alto', 7.5, 'El servidor web remoto utiliza una versión de PHP que presenta múltiples fallos.', 'Según su banner, la versión de PHP instalada en el host remoto es anterior a la 5.2.11. Dichas versiones pueden verse afectadas por varios problemas de seguridad:

Se ha producido un error no especificado en la validación del certificado dentro de ''php_openssl_apply_verification_policy''.

- Una vulnerabilidad de validación de entrada no especificada afecta al índice de color en ''imagecolortransparent()''.

- Una vulnerabilidad de validación de entrada no especificada afecta al procesamiento de EXIF.

- Llamar a ''popen()'' con un modo no válido puede provocar un fallo en Windows. (Error n.º 44683)

- Un desbordamiento de enteros en ''xml_utf8_decode()'' puede facilitar la elusión de los mecanismos de protección contra secuencias de comandos entre sitios (XSS) e inyección SQL mediante una cadena especialmente diseñada con una codificación UTF-8 larga. (Error n.° 49687)

- ''proc_open()'' puede eludir ''safe_mode_protected_env_vars''.

(Error n.° 49026)', 'Actualiza a la versión 5.2.11 de PHP o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2009-3291, CVE-2009-3292, CVE-2009-3293, CVE-2009-3294, CVE-2009-4018, CVE-2009-5016', 'PHP < 5.2.11 Múltiples vulnerabilidades', 'Alto', 7.5, 'El servidor web remoto utiliza una versión de PHP que presenta múltiples fallos.', 'Según su banner, la versión de PHP instalada en el host remoto es anterior a la 5.2.11. Dichas versiones pueden verse afectadas por varios problemas de seguridad:

Se ha producido un error no especificado en la validación del certificado dentro de ''php_openssl_apply_verification_policy''.

- Una vulnerabilidad de validación de entrada no especificada afecta al índice de color en ''imagecolortransparent()''.

- Una vulnerabilidad de validación de entrada no especificada afecta al procesamiento de EXIF.

- Llamar a ''popen()'' con un modo no válido puede provocar un fallo en Windows. (Error n.º 44683)

- Un desbordamiento de enteros en ''xml_utf8_decode()'' puede facilitar la elusión de los mecanismos de protección contra secuencias de comandos entre sitios (XSS) e inyección SQL mediante una cadena especialmente diseñada con una codificación UTF-8 larga. (Error n.° 49687)

- ''proc_open()'' puede eludir ''safe_mode_protected_env_vars''.

(Error n.° 49026)', 'Actualiza a la versión 5.2.11 de PHP o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2007-1581, CVE-2010-0397, CVE-2010-1860, CVE-2010-1862, CVE-2010-1864, CVE-2010-2097, CVE-2010-2100, CVE-2010-2101, CVE-2010-2190, CVE-2010-2191, CVE-2010-2225, CVE-2010-2484, CVE-2010-2531, CVE-2010-3065', 'Múltiples vulnerabilidades en PHP 5.2 < 5.2.14', 'Alto', 7.5, 'El servidor web remoto utiliza una versión de PHP que presenta múltiples fallos.', 'Según su banner, la versión de PHP 5.2 instalada en el host remoto es anterior a la 5.2.14. Dichas versiones pueden verse afectadas por varios problemas de seguridad:

- Se produce un error al procesar solicitudes XML-RPC no válidas que puede provocar una desreferenciación de puntero nulo. (error n.º 51288) (CVE-2010-0397)

- Existe un error en la función ''fnmatch'' que puede provocar el agotamiento de la pila.

- Existe un error en la extensión sqlite que podría permitir el acceso arbitrario a la memoria.

- Existe un error de corrupción de memoria en la función ''substr_replace''.

- Las siguientes funciones no están debidamente protegidas contra interrupciones de funcionamiento:

addcslashes, chunk_split, html_entity_decode, iconv_mime_decode, iconv_substr, iconv_mime_encode, htmlentities, htmlspecialchars, str_getcsv, http_build_query, strpbrk, strstr, str_pad, str_word_count, wordwrap, strtok, setcookie, strip_tags, trim, ltrim, rtrim, parse_str, pack, unpack, uasort, preg_match, strrchr, strchr, substr, str_repeat (CVE-2010-1860, CVE-2010-1862, CVE-2010-1864, CVE-2010-2097, CVE-2010-2100, CVE-2010-2101, CVE-2010-2190, CVE-2010-2191, CVE-2010-2484)

- Los siguientes códigos de operación no están debidamente protegidos contra interrupciones de función:

ZEND_CONCAT, ZEND_ASSIGN_CONCAT, ZEND_FETCH_RW (CVE-2010-2191)

- El serializador de sesión predeterminado contiene un error que puede ser explotado al asignar variables de sesión con nombres definidos por el usuario. Se pueden inyectar valores serializados arbitrarios en las sesiones incluyendo el carácter PS_UNDEF_MARKER, ''!'', en los nombres de las variables.

Existe un error de uso de memoria liberada en la función ''spl_object_storage_attach''. (CVE-2010-2225)

- Existe una vulnerabilidad de divulgación de información en la función ''var_export'' al manejar ciertas condiciones de error. (CVE-2010-2531)', 'Actualiza a la versión 5.2.14 de PHP o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2007-1581, CVE-2010-0397, CVE-2010-1860, CVE-2010-1862, CVE-2010-1864, CVE-2010-2097, CVE-2010-2100, CVE-2010-2101, CVE-2010-2190, CVE-2010-2191, CVE-2010-2225, CVE-2010-2484, CVE-2010-2531, CVE-2010-3065', 'Múltiples vulnerabilidades en PHP 5.2 < 5.2.14', 'Alto', 7.5, 'El servidor web remoto utiliza una versión de PHP que presenta múltiples fallos.', 'Según su banner, la versión de PHP 5.2 instalada en el host remoto es anterior a la 5.2.14. Dichas versiones pueden verse afectadas por varios problemas de seguridad:

- Se produce un error al procesar solicitudes XML-RPC no válidas que puede provocar una desreferenciación de puntero nulo. (error n.º 51288) (CVE-2010-0397)

- Existe un error en la función ''fnmatch'' que puede provocar el agotamiento de la pila.

- Existe un error en la extensión sqlite que podría permitir el acceso arbitrario a la memoria.

- Existe un error de corrupción de memoria en la función ''substr_replace''.

- Las siguientes funciones no están debidamente protegidas contra interrupciones de funcionamiento:

addcslashes, chunk_split, html_entity_decode, iconv_mime_decode, iconv_substr, iconv_mime_encode, htmlentities, htmlspecialchars, str_getcsv, http_build_query, strpbrk, strstr, str_pad, str_word_count, wordwrap, strtok, setcookie, strip_tags, trim, ltrim, rtrim, parse_str, pack, unpack, uasort, preg_match, strrchr, strchr, substr, str_repeat (CVE-2010-1860, CVE-2010-1862, CVE-2010-1864, CVE-2010-2097, CVE-2010-2100, CVE-2010-2101, CVE-2010-2190, CVE-2010-2191, CVE-2010-2484)

- Los siguientes códigos de operación no están debidamente protegidos contra interrupciones de función:

ZEND_CONCAT, ZEND_ASSIGN_CONCAT, ZEND_FETCH_RW (CVE-2010-2191)

- El serializador de sesión predeterminado contiene un error que puede ser explotado al asignar variables de sesión con nombres definidos por el usuario. Se pueden inyectar valores serializados arbitrarios en las sesiones incluyendo el carácter PS_UNDEF_MARKER, ''!'', en los nombres de las variables.

Existe un error de uso de memoria liberada en la función ''spl_object_storage_attach''. (CVE-2010-2225)

- Existe una vulnerabilidad de divulgación de información en la función ''var_export'' al manejar ciertas condiciones de error. (CVE-2010-2531)', 'Actualiza a la versión 5.2.14 de PHP o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2011-3379, CVE-2011-4566, CVE-2011-4885, CVE-2012-0057, CVE-2012-0781, CVE-2012-0788, CVE-2012-0789', 'PHP < 5.3.9 Múltiples vulnerabilidades', 'Alto', 7.5, 'El servidor web remoto utiliza una versión de PHP que presenta múltiples fallos.', 'Según su banner, la versión de PHP instalada en el host remoto es anterior a la 5.3.9. Por lo tanto, puede verse afectada por los siguientes problemas de seguridad:

- La función ''is_a()'' en PHP 5.3.7 y 5.3.8 activa una llamada a ''__autoload()''. (CVE-2011-3379)

Es posible provocar una denegación de servicio enviando múltiples solicitudes especialmente diseñadas que contienen parámetros con valores que causan colisiones de hash al calcular los valores hash para su almacenamiento en una tabla hash. (CVE-2011-4885)

Existe un desbordamiento de enteros en la función exif_process_IFD_TAG del archivo exif.c que puede permitir a un atacante remoto leer ubicaciones de memoria arbitrarias o provocar una denegación de servicio. Esta vulnerabilidad solo afecta a PHP 5.4.0beta2 en plataformas de 32 bits. (CVE-2011-4566)

- Las llamadas a libxslt no están restringidas mediante xsltSetSecurityPrefs(), lo que podría permitir a un atacante crear o sobrescribir archivos, dando lugar a la ejecución de código arbitrario. (CVE-2012-0057)

Existe un error en la función ''tidy_diagnose'' que permite a un atacante provocar que la aplicación acceda a un puntero nulo. Esto causa que la aplicación falle. (CVE-2012-0781)

La implementación de ''PDORow'' contiene un error que puede provocar fallos en la aplicación al interactuar con la función de sesión. (CVE-2012-0788)

- Existe un error en el manejo de la zona horaria que permite que las llamadas repetidas a la función ''strtotime'' posibiliten un ataque de denegación de servicio mediante el consumo de memoria.

(CVE-2012-0789)', 'Actualiza a la versión 5.3.9 de PHP o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2011-3379, CVE-2011-4566, CVE-2011-4885, CVE-2012-0057, CVE-2012-0781, CVE-2012-0788, CVE-2012-0789', 'PHP < 5.3.9 Múltiples vulnerabilidades', 'Alto', 7.5, 'El servidor web remoto utiliza una versión de PHP que presenta múltiples fallos.', 'Según su banner, la versión de PHP instalada en el host remoto es anterior a la 5.3.9. Por lo tanto, puede verse afectada por los siguientes problemas de seguridad:

- La función ''is_a()'' en PHP 5.3.7 y 5.3.8 activa una llamada a ''__autoload()''. (CVE-2011-3379)

Es posible provocar una denegación de servicio enviando múltiples solicitudes especialmente diseñadas que contienen parámetros con valores que causan colisiones de hash al calcular los valores hash para su almacenamiento en una tabla hash. (CVE-2011-4885)

Existe un desbordamiento de enteros en la función exif_process_IFD_TAG del archivo exif.c que puede permitir a un atacante remoto leer ubicaciones de memoria arbitrarias o provocar una denegación de servicio. Esta vulnerabilidad solo afecta a PHP 5.4.0beta2 en plataformas de 32 bits. (CVE-2011-4566)

- Las llamadas a libxslt no están restringidas mediante xsltSetSecurityPrefs(), lo que podría permitir a un atacante crear o sobrescribir archivos, dando lugar a la ejecución de código arbitrario. (CVE-2012-0057)

Existe un error en la función ''tidy_diagnose'' que permite a un atacante provocar que la aplicación acceda a un puntero nulo. Esto causa que la aplicación falle. (CVE-2012-0781)

La implementación de ''PDORow'' contiene un error que puede provocar fallos en la aplicación al interactuar con la función de sesión. (CVE-2012-0788)

- Existe un error en el manejo de la zona horaria que permite que las llamadas repetidas a la función ''strtotime'' posibiliten un ataque de denegación de servicio mediante el consumo de memoria.

(CVE-2012-0789)', 'Actualiza a la versión 5.3.9 de PHP o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2012-1823', 'Ejecución de código de cadena de consulta CGI en PHP < 5.3.12 / 5.4.2', 'Alto', 7.5, 'El servidor web remoto utiliza una versión de PHP que se ve afectada por una vulnerabilidad de ejecución remota de código.', 'Según su banner, la versión de PHP instalada en el host remoto es anterior a la 5.3.12 / 5.4.2 y, como tal, podría verse afectada por una vulnerabilidad de ejecución remota de código y divulgación de información.

Un error en el archivo ''sapi/cgi/cgi_main.c'' puede permitir que un atacante remoto obtenga el código fuente de PHP del servidor web o que ejecute código arbitrario. En configuraciones vulnerables, PHP trata ciertos parámetros de la cadena de consulta como argumentos de la línea de comandos, incluyendo opciones como ''-s'', ''-d'' y ''-c''.

Tenga en cuenta que esta vulnerabilidad solo se puede explotar cuando PHP se utiliza en configuraciones basadas en CGI. Apache con ''mod_php'' no es una configuración explotable.', 'Actualiza a la versión 5.3.12 / 5.4.2 de PHP o posterior. También está disponible una solución alternativa mediante ''mod_rewrite''.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2012-1823', 'Ejecución de código de cadena de consulta CGI en PHP < 5.3.12 / 5.4.2', 'Alto', 7.5, 'El servidor web remoto utiliza una versión de PHP que se ve afectada por una vulnerabilidad de ejecución remota de código.', 'Según su banner, la versión de PHP instalada en el host remoto es anterior a la 5.3.12 / 5.4.2 y, como tal, podría verse afectada por una vulnerabilidad de ejecución remota de código y divulgación de información.

Un error en el archivo ''sapi/cgi/cgi_main.c'' puede permitir que un atacante remoto obtenga el código fuente de PHP del servidor web o que ejecute código arbitrario. En configuraciones vulnerables, PHP trata ciertos parámetros de la cadena de consulta como argumentos de la línea de comandos, incluyendo opciones como ''-s'', ''-d'' y ''-c''.

Tenga en cuenta que esta vulnerabilidad solo se puede explotar cuando PHP se utiliza en configuraciones basadas en CGI. Apache con ''mod_php'' no es una configuración explotable.', 'Actualiza a la versión 5.3.12 / 5.4.2 de PHP o posterior. También está disponible una solución alternativa mediante ''mod_rewrite''.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'PHP < 7.3.24 Múltiples vulnerabilidades', 'Alto', 5.0, 'La versión de PHP que se ejecuta en el servidor web remoto se ve afectada por múltiples vulnerabilidades.', 'Según el número de versión que él mismo ha informado, la versión de PHP que se ejecuta en el servidor web remoto es anterior a la 7.3.24. Por lo tanto, está afectada por múltiples vulnerabilidades.', 'Actualiza a la versión 7.3.24 de PHP o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'PHP < 7.3.24 Múltiples vulnerabilidades', 'Alto', 5.0, 'La versión de PHP que se ejecuta en el servidor web remoto se ve afectada por múltiples vulnerabilidades.', 'Según el número de versión que él mismo ha informado, la versión de PHP que se ejecuta en el servidor web remoto es anterior a la 7.3.24. Por lo tanto, está afectada por múltiples vulnerabilidades.', 'Actualiza a la versión 7.3.24 de PHP o posterior.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2024-40898', 'Múltiples vulnerabilidades en Apache 2.4.x < 2.4.62 (Windows)', 'Alto', 7.8, 'El servidor web remoto se ve afectado por múltiples vulnerabilidades.', 'La versión de Apache httpd instalada en el host remoto es anterior a la 2.4.62. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso de seguridad 2.4.62.

- Una vulnerabilidad SSRF en el servidor HTTP Apache en Windows con mod_rewrite en el contexto del servidor/host virtual permite la posible filtración de hashes NTML a un servidor malicioso mediante SSRF y solicitudes maliciosas. Se recomienda a los usuarios actualizar a la versión 2.4.62, que soluciona este problema. (CVE-2024-40898)', 'Actualice a la versión 2.4.62 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-1333, CVE-2018-8011', 'Múltiples vulnerabilidades en Apache 2.4.x < 2.4.34', 'Alto', 5.0, 'El servidor web remoto se ve afectado por múltiples vulnerabilidades.', 'Según su banner, la versión de Apache que se ejecuta en el host remoto es 2.4.x anterior a 2.4.34. Por lo tanto, se ve afectada por las siguientes vulnerabilidades:

Mediante la manipulación de las solicitudes HTTP/2, se asignaban 60 segundos más de tiempo a los procesos de trabajo de lo necesario, lo que provocaba su agotamiento y una denegación de servicio. (CVE-2018-1333)

- Mediante la manipulación de las solicitudes HTTP, el controlador de desafíos de mod_md podría desreferenciar un puntero nulo y provocar un error de segmentación en el proceso hijo. Esto podría utilizarse para realizar un ataque de denegación de servicio (DoS) contra el servidor. (CVE-2018-8011)', 'Actualice a la versión 2.4.34 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-0196, CVE-2019-0197, CVE-2019-0211, CVE-2019-0215, CVE-2019-0217, CVE-2019-0220', 'Múltiples vulnerabilidades en Apache 2.4.x < 2.4.39', 'Alto', 7.2, 'El servidor web remoto se ve afectado por múltiples vulnerabilidades.', 'Según su banner, la versión de Apache que se ejecuta en el host remoto es 2.4.x anterior a la 2.4.39. Por lo tanto, se ve afectada por múltiples vulnerabilidades:

- Existe una vulnerabilidad de escalada de privilegios en los scripts de los módulos debido a la capacidad de ejecutar código arbitrario como proceso padre mediante la manipulación del marcador. (CVE-2019-0211)

Existe una vulnerabilidad de omisión del control de acceso en mod_auth_digest debido a una condición de carrera al ejecutarse en un servidor multihilo. Un atacante con credenciales válidas podría autenticarse utilizando otro nombre de usuario. (CVE-2019-0217)

- Existe una vulnerabilidad de omisión del control de acceso en mod_ssl al utilizar la verificación de certificados de cliente por ubicación con TLSv1.3. (CVE-2019-0215)

Además, Apache httpd también se ve afectado por varias vulnerabilidades adicionales, entre las que se incluyen una denegación de servicio, lectura después de la liberación de memoria e inconsistencias en la normalización de rutas URL.', 'Actualice a la versión 2.4.39 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-17189, CVE-2018-17199, CVE-2019-0190', 'Múltiples vulnerabilidades en Apache 2.4.x < 2.4.38', 'Alto', 5.0, 'El servidor web remoto se ve afectado por múltiples vulnerabilidades.', 'Según su banner, la versión de Apache que se ejecuta en el host remoto es 2.4.x anterior a la 2.4.38. Por lo tanto, se ve afectada por múltiples vulnerabilidades:

Existe una vulnerabilidad de denegación de servicio (DoS) en el manejo de flujos HTTP/2. Un atacante remoto no autenticado puede explotar esta vulnerabilidad enviando cuerpos de solicitud de forma lenta a recursos no utilizados, ocupando así un hilo del servidor. (CVE-2018-17189)

- Existe una vulnerabilidad en mod_sesion_cookie, ya que no comprueba correctamente el tiempo de caducidad de las cookies. (CVE-2018-17199)

Existe una vulnerabilidad de denegación de servicio (DoS) en mod_ssl al utilizarse con OpenSSL 1.1.1 debido a una interacción en los cambios en el manejo de los intentos de renegociación. Un atacante remoto no autenticado puede explotar esta vulnerabilidad para provocar que mod_ssl deje de responder. (CVE-2019-0190)', 'Actualice a la versión 2.4.38 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2022-26377', 'Vulnerabilidad de contrabando de solicitudes HTTP en Apache 2.4.x < 2.4.54', 'Alto', 5.0, 'El servidor web remoto se ve afectado por una vulnerabilidad de contrabando de solicitudes HTTP.', 'La versión de Apache httpd instalada en el host remoto es anterior a la 2.4.54. Por lo tanto, se ve afectada por una vulnerabilidad de contrabando de solicitudes HTTP, tal como se menciona en el aviso de seguridad de la versión 2.4.54.

- Posible contrabando de solicitudes en mod_proxy_ajp: La vulnerabilidad de interpretación inconsistente de solicitudes HTTP (''contrabando de solicitudes HTTP'') en mod_proxy_ajp del servidor HTTP Apache permite a un atacante contrabandear solicitudes al servidor AJP al que reenvía las solicitudes. Este problema afecta a Apache HTTP Server versión 2.4.53 y versiones anteriores. Agradecimientos: Ricter Z @ 360 Noah Lab', 'Actualice a la versión 2.4.54 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2022-30522', 'Múltiples vulnerabilidades en Apache 2.4.x < 2.4.54', 'Alto', 5.0, 'El servidor web remoto se ve afectado por múltiples vulnerabilidades.', 'La versión de Apache httpd instalada en el host remoto es anterior a la 2.4.54. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso de seguridad de la versión 2.4.54.

Denegación de servicio mod_sed: Si Apache HTTP Server 2.4.53 está configurado para realizar transformaciones con mod_sed en contextos donde la entrada a mod_sed puede ser muy grande, mod_sed puede realizar asignaciones de memoria excesivamente grandes y provocar una interrupción. Agradecimientos: Este problema fue descubierto por Brian Moussalli del equipo de investigación de seguridad de JFrog.', 'Actualice a la versión 2.4.54 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2022-29404, CVE-2022-30556', 'Múltiples vulnerabilidades en Apache 2.4.x < 2.4.54 (mod_lua)', 'Alto', 5.0, 'El servidor web remoto se ve afectado por múltiples vulnerabilidades.', 'La versión de Apache httpd instalada en el host remoto es anterior a la 2.4.54. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso de seguridad de la versión 2.4.54.

- Denegación de servicio en mod_lua r:parsebody: En Apache HTTP Server 2.4.53 y versiones anteriores, una solicitud maliciosa a un script Lua que llama a r:parsebody(0) puede provocar una denegación de servicio debido a la ausencia de un límite predeterminado en el tamaño de entrada posible. Agradecimientos: El proyecto Apache HTTP Server agradece a Ronald Crane (Zippenhop LLC) por informar sobre este problema (CVE-2022-29404).

Divulgación de información en mod_lua con websockets: Apache HTTP Server 2.4.53 y versiones anteriores pueden devolver longitudes a las aplicaciones que llaman a r:wsread() que apuntan más allá del final del almacenamiento asignado para el búfer.

Agradecimientos: El proyecto del servidor HTTP Apache desea agradecer a Ronald Crane (Zippenhop LLC) por informar sobre este problema (CVE-2022-30556).', 'Actualice a la versión 2.4.54 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2023-43622, CVE-2023-45802', 'Múltiples vulnerabilidades en Apache 2.4.x < 2.4.58', 'Alto', 7.8, 'El servidor web remoto se ve afectado por múltiples vulnerabilidades.', 'La versión de Apache httpd instalada en el host remoto es anterior a la 2.4.58. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso de seguridad 2.4.58.

Servidor HTTP Apache: Ataque DoS en HTTP/2 con ventana inicial de tamaño 0: Un atacante, al abrir una conexión HTTP/2 con una ventana inicial de tamaño 0, podía bloquear indefinidamente el manejo de dicha conexión en el servidor HTTP Apache. Esto podía utilizarse para agotar los recursos del servidor, de forma similar al conocido ataque Slow Loris. Este problema se ha corregido en la versión 2.4.58, de modo que dichas conexiones se finalizan correctamente tras el tiempo de espera configurado. Este problema afecta al servidor HTTP Apache desde la versión 2.4.55 hasta la 2.4.57. Se recomienda a los usuarios actualizar a la versión 2.4.58, que soluciona el problema.

Agradecimientos: (CVE-2023-43622)

Servidor HTTP Apache: La memoria del flujo HTTP/2 no se libera inmediatamente al reiniciarse (RST): Cuando un cliente reiniciaba un flujo HTTP/2 (trama RST), existía un lapso de tiempo durante el cual los recursos de memoria de la solicitud no se liberaban de inmediato. En su lugar, la liberación se posponía hasta el cierre de la conexión. Un cliente podía enviar nuevas solicitudes y reinicios, manteniendo la conexión ocupada y abierta, lo que provocaba un aumento continuo del consumo de memoria. Al cerrarse la conexión, se liberaban todos los recursos, pero el proceso podía quedarse sin memoria antes. Este problema fue detectado por el usuario durante las pruebas de la vulnerabilidad CVE-2023-44487 (HTTP/2 Rapid Reset Exploit) con su propio cliente de prueba. Durante el uso normal de HTTP/2, la probabilidad de encontrar este error es muy baja. La memoria retenida no se haría perceptible antes de que la conexión se cerrara o expirara el tiempo de espera. Se recomienda a los usuarios actualizar a la versión 2.4.58, que soluciona el problema. Agradecimientos: (CVE-2023-45802)', 'Actualice a la versión 2.4.58 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2023-31122', 'Lectura fuera de límites en Apache 2.4.x < 2.4.58 (CVE-2023-31122)', 'Alto', 7.8, 'El servidor web remoto se ve afectado por una vulnerabilidad de lectura fuera de límites.', 'La versión de Apache httpd instalada en el host remoto es anterior a la 2.4.58. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso de seguridad 2.4.58.

- Vulnerabilidad de lectura fuera de límites en mod_macro: Vulnerabilidad de lectura fuera de límites en mod_macro del servidor HTTP Apache. Este problema afecta al servidor HTTP Apache hasta la versión 2.4.57.', 'Actualice a la versión 2.4.58 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2023-38709, CVE-2024-24795, CVE-2024-27316', 'Múltiples vulnerabilidades en Apache 2.4.x < 2.4.59', 'Alto', 7.8, 'El servidor web remoto se ve afectado por múltiples vulnerabilidades.', 'La versión de Apache httpd instalada en el host remoto es anterior a la 2.4.59. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso de seguridad 2.4.59.

- Servidor HTTP Apache: División de la respuesta HTTP en varios módulos: La división de la respuesta HTTP en varios módulos en el servidor HTTP Apache permite que un atacante que pueda inyectar encabezados de respuesta maliciosos en las aplicaciones de backend provoque un ataque de desincronización HTTP. Se recomienda a los usuarios actualizar a la versión 2.4.59, que soluciona este problema. Agradecimientos: (CVE-2024-24795)

Servidor HTTP Apache: Ataque DoS HTTP/2 por agotamiento de memoria en tramas de continuación infinitas: Las cabeceras HTTP/2 entrantes que superan el límite se almacenan temporalmente en nghttp2 para generar una respuesta HTTP 413 informativa. Si un cliente no deja de enviar cabeceras, esto provoca un agotamiento de la memoria.

Agradecimientos: descubridor: Bartek Nowotarski (https://nowotarski.info/) (CVE-2024-27316)', 'Actualice a la versión 2.4.59 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2024-42516, CVE-2024-43204, CVE-2024-43394, CVE-2024-47252, CVE-2025-23048, CVE-2025-49630, CVE-2025-49812, CVE-2025-53020', 'Múltiples vulnerabilidades en Apache 2.4.x < 2.4.64', 'Alto', 4.3, 'El servidor web remoto se ve afectado por múltiples vulnerabilidades.', 'La versión de Apache httpd instalada en el host remoto es anterior a la 2.4.64. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso de seguridad de la versión 2.4.64.

- En ciertas configuraciones de proxy, un ataque de denegación de servicio contra las versiones 2.4.26 a 2.4.63 del servidor HTTP Apache puede ser desencadenado por clientes no confiables que provocan una aserción en mod_proxy_http2.

Las configuraciones afectadas son aquellas en las que se configura un proxy inverso para un backend HTTP/2, con ProxyPreserveHost activado. (CVE-2025-49630)

- La división de la respuesta HTTP en el núcleo del servidor HTTP Apache permite que un atacante que pueda manipular los encabezados de respuesta Content-Type de las aplicaciones alojadas o a las que el servidor hace referencia pueda dividir la respuesta HTTP.

Esta vulnerabilidad se describió como CVE-2023-38709, pero el parche incluido en Apache HTTP Server 2.4.59 no solucionó el problema. Se recomienda a los usuarios actualizar a la versión 2.4.64, que corrige este error.

(CVE-2024-42516)

Una vulnerabilidad SSRF en el servidor HTTP Apache con mod_proxy cargado permite a un atacante enviar solicitudes proxy salientes a una URL controlada por él. Requiere una configuración poco común donde mod_headers está configurado para modificar el encabezado Content-Type de la solicitud o respuesta con un valor proporcionado en la solicitud HTTP. Se recomienda a los usuarios actualizar a la versión 2.4.64, que soluciona este problema. (CVE-2024-43204)

La falsificación de solicitudes del lado del servidor (SSRF) en Apache HTTP Server para Windows permite la posible filtración de hashes NTLM a un servidor malicioso mediante expresiones de mod_rewrite o Apache que procesan solicitudes no validadas. Este problema afecta a Apache HTTP Server desde la versión 2.4.0 hasta la 2.4.63. Nota: El proyecto Apache HTTP Server endurecerá los criterios para aceptar informes de vulnerabilidades relacionadas con SSRF a través de rutas UNC. El servidor ofrece protección limitada contra administradores que le ordenen abrir rutas UNC. Los servidores Windows deben limitar los hosts a los que se conectan mediante SMB según la naturaleza de la autenticación NTLM.

(CVE-2024-43394)

El escape insuficiente de datos proporcionados por el usuario en mod_ssl en Apache HTTP Server 2.4.63 y versiones anteriores permite que un cliente SSL/TLS no confiable inserte caracteres de escape en los archivos de registro en algunas configuraciones. En una configuración de registro donde se usa CustomLog con %{varname}x o %{varname}c para registrar variables proporcionadas por mod_ssl, como SSL_TLS_SNI, ni mod_log_config ni mod_ssl realizan ningún escape, y pueden aparecer datos no sanitizados proporcionados por el cliente en los archivos de registro. (CVE-2024-47252)', 'Actualice a la versión 2.4.64 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2021-33193', 'Apache >= 2.4.17 < 2.4.49 mod_http2', 'Alto', 5.0, 'El servidor web remoto se ve afectado por una vulnerabilidad.', 'La versión de Apache httpd instalada en el host remoto es superior a 2.4.17 y anterior a 2.4.49. Por lo tanto, se ve afectada por una vulnerabilidad mencionada en el registro de cambios de la versión 2.4.49. Un método manipulado enviado a través de HTTP/2 eludirá la validación y será reenviado por mod_proxy, lo que puede provocar la división de solicitudes o el envenenamiento de la caché.', 'Actualice a la versión 2.4.49 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2021-36160', 'Apache >= 2.4.30 < 2.4.49 mod_proxy_uwsgi', 'Alto', 5.0, 'El servidor web remoto se ve afectado por una vulnerabilidad.', 'La versión de Apache httpd instalada en el host remoto es superior a la 2.4.30 y anterior a la 2.4.49. Por lo tanto, se ve afectada por una vulnerabilidad mencionada en el registro de cambios de la versión 2.4.49. Una ruta URI de solicitud cuidadosamente diseñada puede provocar que mod_proxy_uwsgi lea más allá de la memoria asignada y falle (denegación de servicio).', 'Actualice a la versión 2.4.49 o posterior de Apache.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-1543', 'Vulnerabilidad en OpenSSL 1.1.0 < 1.1.0k', 'Alto', 5.8, 'El servicio remoto se ve afectado por una vulnerabilidad.', 'La versión de OpenSSL instalada en el host remoto es anterior a la 1.1.0k. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso de seguridad de la versión 1.1.0k.

ChaCha20-Poly1305 es un cifrado AEAD y requiere un valor nonce único para cada operación de cifrado. El RFC 7539 especifica que el valor nonce (IV) debe ser de 96 bits (12 bytes). OpenSSL permite una longitud de nonce variable y rellena el nonce con ceros si es menor de 12 bytes. Sin embargo, también permite incorrectamente que se establezca un nonce de hasta 16 bytes. En este caso, solo los últimos 12 bytes son relevantes y se ignoran los bytes iniciales adicionales. Es requisito indispensable para usar este cifrado que los valores nonce sean únicos. Los mensajes cifrados con un valor nonce reutilizado son vulnerables a graves ataques de confidencialidad e integridad. Si una aplicación cambia la longitud predeterminada del nonce a más de 12 bytes y luego modifica los bytes iniciales del nonce esperando que el nuevo valor sea un nonce único, podría cifrar mensajes inadvertidamente con un nonce reutilizado. Además, los bytes ignorados en un nonce largo no están cubiertos por la garantía de integridad de este cifrado. Cualquier aplicación que dependa de la integridad de estos bytes iniciales ignorados de un nonce largo podría verse afectada. El uso interno de este cifrado por parte de OpenSSL, incluso en SSL/TLS, es seguro, ya que ningún uso de este tipo establece un valor de nonce tan largo. Sin embargo, las aplicaciones de usuario que utilizan este cifrado directamente y establecen una longitud de nonce no predeterminada superior a 12 bytes podrían ser vulnerables. Las versiones 1.1.1 y 1.1.0 de OpenSSL se ven afectadas por este problema.

Debido al alcance limitado de las implementaciones afectadas, se ha evaluado como de baja gravedad y, por lo tanto, no se crearán nuevas versiones por el momento. Solucionado en OpenSSL 1.1.1c (afectado a las versiones 1.1.1-1.1.1b). Solucionado en OpenSSL 1.1.0k (afectado a las versiones 1.1.0-1.1.0j). (CVE-2019-1543)', 'Actualiza a la versión 1.1.0k o posterior de OpenSSL.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2013-5475', 'Vulnerabilidad de denegación de servicio DHCP en el software Cisco IOS (cisco-sa-20130925-dhcp)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Existe una vulnerabilidad en la implementación DHCP del software Cisco IOS que podría permitir a un atacante remoto no autenticado provocar una denegación de servicio (DoS). Esta vulnerabilidad se produce durante el análisis de paquetes DHCP manipulados. Un atacante podría explotarla enviando dichos paquetes a un dispositivo afectado que tenga habilitada la función de servidor DHCP o de retransmisión DHCP. La explotación de esta vulnerabilidad podría permitir al atacante provocar el reinicio del dispositivo afectado.

Cisco ha publicado actualizaciones de software gratuitas que solucionan esta vulnerabilidad. No existen soluciones alternativas para esta vulnerabilidad.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20130925-dhcp.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2013-5474', 'Vulnerabilidad de denegación de servicio por reensamblaje de fragmentación virtual IPv6 en el software Cisco IOS (cisco-sa-20130925-ipv6vfr)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Una vulnerabilidad en la implementación de la función de reensamblaje de fragmentación virtual (VFR) para IPv6 en el software Cisco IOS podría permitir que un atacante remoto no autenticado provoque que un dispositivo afectado se bloquee o se reinicie, resultando en una denegación de servicio (DoS). La vulnerabilidad se debe a una condición de carrera al acceder a la cola de reensamblaje de fragmentos IPv6. Un atacante podría explotar esta vulnerabilidad enviando un flujo manipulado de fragmentos IPv6 válidos. La explotación repetida podría resultar en una denegación de servicio sostenida. Cisco ha publicado actualizaciones de software gratuitas que solucionan esta vulnerabilidad. No existen soluciones alternativas para esta vulnerabilidad.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20130925-ipv6vfr.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2013-5479, CVE-2013-5480, CVE-2013-5481', 'Vulnerabilidades de traducción de direcciones de red en el software Cisco IOS (cisco-sa-20130925-nat)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'La implementación de la función de traducción de direcciones de red (NAT) en el software Cisco IOS presenta tres vulnerabilidades al traducir paquetes IP que podrían permitir a un atacante remoto no autenticado provocar una denegación de servicio (DoS). Cisco ha publicado actualizaciones de software gratuitas que solucionan estas vulnerabilidades.

No existen soluciones alternativas que mitiguen estas vulnerabilidades.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20130925-nat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2013-5478', 'Vulnerabilidad de cuña en la interfaz del protocolo de reserva de recursos de software de Cisco IOS (cisco-sa-20130925-rsvp)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'El dispositivo remoto se ve afectado por una vulnerabilidad de denegación de servicio debido al manejo inadecuado de los paquetes UDP RSVP en la función de Protocolo de Reserva de Recursos (RSVP). Un atacante remoto no autenticado, mediante paquetes UDP RSVP especialmente diseñados y enviados al puerto 1698, puede provocar una saturación de la cola de la interfaz, lo que resulta en la pérdida de conectividad, la pérdida de adyacencia del protocolo de enrutamiento y otras condiciones de denegación de servicio.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20130925-rsvp. Como alternativa, aplique la solución alternativa que se menciona en el aviso.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2014-2112', 'Denegación de servicio en la VPN SSL del software Cisco IOS (cisco-sa-20140326-ios-sslvpn)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la información proporcionada por el propio sistema, la versión de Cisco IOS que se ejecuta en el host remoto se ve afectada por una vulnerabilidad de denegación de servicio debido a un manejo inadecuado de ciertos tipos de solicitudes HTTP no especificados en el subsistema SSL VPN. Un atacante remoto no autenticado podría explotar esta vulnerabilidad enviando solicitudes HTTP especialmente diseñadas, lo que provocaría una denegación de servicio.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20140326-ios-sslvpn.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2014-2108', 'Denegación de servicio en el intercambio de claves de Internet versión 2 (IKEv2) del software Cisco IOS (cisco-sa-20140326-ikev2)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han comunicado, la versión de Cisco IOS que se ejecuta en el host remoto se ve afectada por una vulnerabilidad de denegación de servicio en el módulo de Intercambio de Claves de Internet versión 2 (IKEv2).

Un atacante remoto no autenticado podría explotar este problema enviando un paquete IKEv2 mal formado, lo que provocaría una denegación de servicio.

Tenga en cuenta que este problema solo afecta a los hosts cuando el Protocolo de administración de claves y asociación de seguridad de Internet (ISAKMP) está habilitado.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20140326-ikev2.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2014-2113', 'Denegación de servicio IPv6 del software Cisco IOS (cisco-sa-20140326-ipv6)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la información proporcionada por el propio sistema, la versión de Cisco IOS que se ejecuta en el host remoto se ve afectada por una vulnerabilidad de denegación de servicio en la pila de protocolos IPv6. Este problema se debe a un manejo inadecuado de ciertos tipos de paquetes IPv6 no especificados. Un atacante remoto no autenticado podría explotar esta vulnerabilidad enviando un paquete IPv6 especialmente diseñado, lo que provocaría una denegación de servicio.

Tenga en cuenta que esto solo afecta a los hosts con IPv6 habilitado.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20140326-ipv6.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2014-2109, CVE-2014-2111', 'Vulnerabilidades de denegación de servicio por traducción de direcciones de red (NAT) múltiple en el software Cisco IOS (cisco-sa-20140326-nat)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han informado, la versión de Cisco IOS que se ejecuta en el host remoto se ve afectada por múltiples vulnerabilidades de denegación de servicio en la implementación de la traducción de direcciones de red (NAT):

- Existe un problema en el módulo de entrada TCP debido al manejo incorrecto de ciertas secuencias de paquetes TCP.

Un atacante remoto no autenticado podría explotar esta vulnerabilidad enviando una secuencia específica de paquetes TCP IPv4, lo que provocaría una denegación de servicio.

(CVE-2014-2109)

Existe un problema en el módulo Application Layer Gateway (ALG) debido al manejo incorrecto de paquetes DNS mal formados durante el procedimiento NAT. Un atacante remoto no autenticado podría explotar este problema enviando paquetes DNS IPv4 mal formados, lo que provocaría una denegación de servicio. (CVE-2014-2111)

Tenga en cuenta que los paquetes IPv6 no se pueden utilizar para explotar estas vulnerabilidades.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20140326-nat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2014-3355, CVE-2014-3356', 'Múltiples vulnerabilidades de flujo de metadatos IPv6 en el software Cisco IOS (cisco-sa-20140924-metadata)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la información proporcionada por el propio sistema, la versión de Cisco IOS que se ejecuta en el host remoto se ve afectada por dos vulnerabilidades en la función de flujo de metadatos IPv6 debido a un manejo inadecuado de los paquetes RSVP. Un atacante remoto puede explotar este problema enviando flujos RSVP especialmente diseñados para provocar el reinicio del dispositivo.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20140924-metadata.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2014-3361', 'Módulo ALG de traducción de direcciones de red (NAT) del software Cisco IOS DoS (cisco-sa-20140924-nat)', 'Alto', 7.1, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han reportado, la versión de Cisco IOS que se ejecuta en el host remoto se ve afectada por una vulnerabilidad de denegación de servicio en el módulo de puerta de enlace de capa de aplicación (ALG) de traducción de direcciones de red (NAT). Este problema se debe a un manejo inadecuado del protocolo de descripción de sesión (SDP) multiparte en los mensajes del protocolo de inicio de sesión (SIP). Un atacante remoto puede explotar esta vulnerabilidad enviando mensajes SIP especialmente diseñados.

Tenga en cuenta que la configuración afectada no está habilitada de forma predeterminada.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20140924-nat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2014-3354', 'Software Cisco IOS RSVP DoS (cisco-sa-20140924-rsvp)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han informado, la versión de Cisco IOS que se ejecuta en el host remoto se ve afectada por una vulnerabilidad de denegación de servicio en la implementación del Protocolo de Reserva de Recursos (RSVP) debido a un manejo inadecuado de los paquetes RSVP. Un atacante remoto puede explotar esta vulnerabilidad enviando paquetes RSVP especialmente diseñados para provocar el reinicio del dispositivo.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20140924-rsvp.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2015-0209, CVE-2015-0286, CVE-2015-0287, CVE-2015-0288, CVE-2015-0289, CVE-2015-0292, CVE-2015-0293', 'Múltiples vulnerabilidades de OpenSSL en Cisco IOS (CSCut46130)', 'Alto', 7.5, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Al dispositivo Cisco IOS remoto le falta un parche de seguridad proporcionado por el fabricante y tiene un servicio IOS configurado para usar TLS o SSL. Por lo tanto, se ve afectado por las siguientes vulnerabilidades en la biblioteca OpenSSL incluida:

La función d2i_ECPrivateKey() presenta una vulnerabilidad de uso de memoria liberada debido al procesamiento incorrecto de archivos de clave privada EC mal formados durante la importación. Un atacante remoto puede explotar esta vulnerabilidad para desreferenciar o liberar memoria ya liberada, lo que podría provocar una denegación de servicio u otro impacto no especificado. (CVE-2015-0209)

Se ha producido un error de lectura no válida en la función ASN1_TYPE_cmp() debido a comparaciones de tipo booleano realizadas incorrectamente. Un atacante remoto puede explotar esta vulnerabilidad, mediante un certificado X.509 manipulado dirigido a un punto final que utilice la función de verificación de certificados, para provocar una operación de lectura no válida y, en consecuencia, una denegación de servicio.

(CVE-2015-0286)

- Existe un fallo en la función ASN1_item_ex_d2i() debido a un error al reiniciar las estructuras de datos ''CHOICE'' y ''ADB'' al reutilizar una estructura en el análisis ASN.1.

Esto permite que un atacante remoto provoque una operación de escritura no válida y corrupción de memoria, lo que resulta en una denegación de servicio. (CVE-2015-0287)

Existe una vulnerabilidad de desreferenciación de puntero nulo en la función X509_to_X509_REQ() debido a un procesamiento incorrecto de las claves del certificado. Esto permite que un atacante remoto, mediante un certificado X.509 manipulado, provoque una denegación de servicio. (CVE-2015-0288)

Existe una vulnerabilidad de desreferenciación de puntero nulo en el código de análisis de PKCS#7 debido a un manejo incorrecto de la información de contenido externa faltante. Esto permite que un atacante remoto, utilizando una aplicación que procesa datos PKCS#7 arbitrarios y proporcionando datos mal formados con codificación ASN.1, provoque una denegación de servicio. (CVE-2015-0289)

Existe una condición de subdesbordamiento de enteros en la función EVP_DecodeUpdate() debido a una validación incorrecta de la entrada codificada en base64 durante la decodificación. Esto permite que un atacante remoto, utilizando datos base64 manipulados maliciosamente, provoque un fallo de segmentación o corrupción de memoria, lo que resulta en una denegación de servicio o posiblemente en la ejecución de código arbitrario. (CVE-2015-0292)

Existe una vulnerabilidad en los servidores que admiten SSLv2 y permiten la exportación de conjuntos de cifrado debido a una implementación incorrecta de SSLv2. Un atacante remoto puede explotar esta vulnerabilidad, mediante un mensaje CLIENT-MASTER-KEY manipulado, para provocar una denegación de servicio. (CVE-2015-0293)', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCut46130.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2015-0642, CVE-2015-0643', 'Cisco IOS IKEv2 DoS (cisco-sa-20150325-ikev2)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han reportado, el software Cisco IOS que se ejecuta en el dispositivo remoto se ve afectado por una vulnerabilidad de denegación de servicio en el subsistema de Intercambio de Claves de Internet versión 2 (IKEv2) debido a un manejo inadecuado de paquetes IKEv2 especialmente diseñados. Un atacante remoto no autenticado puede explotar esta vulnerabilidad para provocar el reinicio del dispositivo o agotar los recursos de memoria.

Tenga en cuenta que este problema solo afecta a los dispositivos con IKEv1 o ISAKMP habilitados.', 'Aplique el parche correspondiente al que se hace referencia en el aviso de seguridad de Cisco.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2016-1344', 'DoS de fragmentación de Cisco IOS IKEv2 (cisco-sa-20160323-ios-ikev2)', 'Alto', 7.1, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han informado, el software Cisco IOS que se ejecuta en el dispositivo remoto se ve afectado por una vulnerabilidad de denegación de servicio en el subsistema de Intercambio de Claves de Internet versión 2 (IKEv2) debido a un manejo inadecuado de los paquetes IKEv2 fragmentados. Un atacante remoto no autenticado puede explotar esta vulnerabilidad, mediante paquetes UDP especialmente diseñados, para provocar el reinicio del dispositivo.

Tenga en cuenta que este problema solo afecta a los dispositivos con la fragmentación IKEv2 habilitada y está configurado para cualquier tipo de VPN basada en IKEv2.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCux38417. Como alternativa, aplique la solución alternativa que se menciona en el aviso del proveedor.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2016-6415', 'Divulgación remota de información en el manejo de paquetes IKEv1 de Cisco IOS (cisco-sa-20160916-ikev1) (BENIGNCERTAIN)', 'Alto', 5.0, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión y configuración que el propio dispositivo ha declarado, el software Cisco IOS que se ejecuta en el dispositivo remoto se ve afectado por una vulnerabilidad de divulgación de información, conocida como BENIGNCERTAIN, en el subsistema de Intercambio de Claves de Internet versión 1 (IKEv1) debido a un manejo inadecuado de las solicitudes de negociación de seguridad de IKEv1. Un atacante remoto no autenticado puede explotar esta vulnerabilidad, mediante un paquete IKEv1 especialmente diseñado, para revelar el contenido de la memoria, lo que resulta en la divulgación de información confidencial, incluidas credenciales y configuraciones.

BENIGNCERTAIN es una de las múltiples vulnerabilidades y exploits de Equation Group revelados el 14/08/2016 por un grupo conocido como Shadow Brokers.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCvb29204.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2016-6393', 'DoS de inicio de sesión AAA de Cisco IOS (cisco-sa-20160928-aaados)', 'Alto', 7.1, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que Cisco ha reportado, su sistema operativo IOS se ve afectado por una vulnerabilidad de denegación de servicio (DoS) en el servicio de autenticación, autorización y contabilidad (AAA) para conexiones remotas de Secure Shell Host (SSH). Un atacante remoto no autenticado puede explotar esta vulnerabilidad intentando autenticarse en el dispositivo objetivo, lo que provoca que este deje de responder.

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el/los ID de error de Cisco CSCuy87667.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2016-6380', 'Vulnerabilidad de denegación de servicio en el reenviador DNS del software Cisco IOS (cisco-sa-20160928-dns)', 'Alto', 8.3, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han informado, IOS se ve afectado por una o más vulnerabilidades. Consulte los BID de Cisco incluidos y el aviso de seguridad de Cisco para obtener más información.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el/los ID de error de Cisco CSCup90532.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2016-6384', 'Ataque de denegación de servicio (DoS) por validación de mensajes H.323 en Cisco IOS (cisco-sa-20160928-h323)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que Cisco ha reportado, el software IOS de Cisco se ve afectado por una vulnerabilidad en el subsistema H.323 debido a un fallo en la validación de ciertos campos en un mensaje del protocolo H.323. Un atacante remoto no autenticado podría explotar esta vulnerabilidad enviando un mensaje malicioso, lo que provocaría que el dispositivo afectado intentara acceder a una región de memoria no válida, se bloqueara y se reiniciara.

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCux04257.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2016-6381', 'DoS de fragmentación de Cisco IOS IKEv1 (cisco-sa-20160928-ios-ikev1)', 'Alto', 7.1, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión y configuración que el propio dispositivo ha declarado, el software Cisco IOS que se ejecuta en el dispositivo remoto se ve afectado por una vulnerabilidad de denegación de servicio en el subsistema de Intercambio de Claves de Internet versión 1 (IKEv1) debido a un manejo inadecuado de los paquetes IKEv1 fragmentados. Un atacante remoto no autenticado puede explotar esta vulnerabilidad, mediante paquetes IKEv1 especialmente diseñados, para provocar el reinicio del dispositivo.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCuy47382. Como solución alternativa, puede deshabilitar la fragmentación de IKEv2 mediante el comando ''no crypto isakmp fragmentation''.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2016-6382, CVE-2016-6392', 'Enrutamiento multicast de Cisco IOS contra múltiples ataques DoS (cisco-sa-20160928-msdp)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según su número de versión y configuración autoinformados, el dispositivo Cisco IOS remoto se ve afectado por múltiples vulnerabilidades de denegación de servicio:

Existe una vulnerabilidad de denegación de servicio debido a una validación incorrecta de los paquetes encapsulados en un mensaje de registro PIM. Un atacante remoto no autenticado puede explotarla enviando un paquete de registro PIM IPv6 a un punto de encuentro PIM (RP) para provocar el reinicio del dispositivo.

(CVE-2016-6382)

Existe una vulnerabilidad de denegación de servicio en la implementación del Protocolo de descubrimiento de origen multicast (MSDP) IPv4 debido a una validación incorrecta de los mensajes Source-Active (SA) recibidos de un par MSDP configurado. Un atacante remoto no autenticado puede explotar esta vulnerabilidad para provocar el reinicio del dispositivo.

(CVE-2016-6392)', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el aviso de seguridad de Cisco cisco-sa-20160928-msdp.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2017-3864', 'Cliente DHCP de Cisco IOS DoS (cisco-sa-20170322-dhcpc)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han reportado, el software Cisco IOS que se ejecuta en el dispositivo remoto se ve afectado por una vulnerabilidad de denegación de servicio en la implementación del cliente DHCP al analizar los paquetes DHCP. Un atacante remoto no autenticado puede explotar esta vulnerabilidad, mediante paquetes DHCP especialmente diseñados, para provocar el reinicio del dispositivo.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCuu43892.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2017-3857', 'Ataque de denegación de servicio (DoS) por análisis de L2TP en Cisco IOS (cisco-sa-20170322-l2tp)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han reportado, el software Cisco IOS que se ejecuta en el dispositivo remoto se ve afectado por una vulnerabilidad de denegación de servicio en su función de análisis del Protocolo de Túnel de Capa 2 (L2TP) debido a una validación insuficiente de los paquetes L2TP. Un atacante remoto no autenticado puede explotar este problema, mediante un paquete L2TP especialmente diseñado, para provocar el reinicio del dispositivo.

Tenga en cuenta que este problema solo afecta a los dispositivos si la función L2TP está habilitada y el dispositivo está configurado como un punto final L2TP versión 2 (L2TPv2) o L2TP versión 3 (L2TPv3). De forma predeterminada, la función L2TP no está habilitada.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCuy82078.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2017-12237', 'Vulnerabilidad de denegación de servicio por intercambio de claves de Internet en el software Cisco IOS', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han informado, IOS se ve afectado por una o más vulnerabilidades. Consulte los BID de Cisco incluidos y el aviso de seguridad de Cisco para obtener más información.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el/los ID de error de Cisco CSCvc41277.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-0159', 'Cisco IOS Software Internet Key Exchange versión 1 DoS (cisco-sa-20180328-ike-dos)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que Cisco ha reportado, su sistema operativo IOS se ve afectado por una vulnerabilidad de denegación de servicio (DoS) en su funcionalidad de Intercambio de Claves de Internet versión 1 (IKEv1) debido a una validación incorrecta de ciertos paquetes IKEv1. Un atacante remoto no autenticado puede explotar esta vulnerabilidad enviando paquetes IKEv1 manipulados a un dispositivo afectado durante una negociación IKE. Si la explotación es exitosa, el atacante puede provocar que el dispositivo afectado se reinicie, lo que resulta en una denegación de servicio.

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el/los ID de error de Cisco CSCuj73916.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-0167, CVE-2018-0175', 'Vulnerabilidades de desbordamiento de búfer en el protocolo de descubrimiento de capa de enlace del software Cisco IOS (cisco-sa-20180328-lldp)', 'Alto', 8.3, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han informado, IOS se ve afectado por una o más vulnerabilidades. Consulte los BID de Cisco incluidos y el aviso de seguridad de Cisco para obtener más información.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en los ID de error de Cisco CSCvd73487 y CSCvd73664.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-1737', 'Vulnerabilidad de denegación de servicio (Denegación de Servicio) en el Acuerdo de Nivel de Servicio IP del software Cisco IOS', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según su propia versión, el software Cisco IOS se ve afectado por una vulnerabilidad en el procesamiento de paquetes IP Service Level Agreement (SLA). Esta vulnerabilidad podría permitir que un atacante remoto no autenticado provoque un bloqueo de interfaz y, en consecuencia, una denegación de servicio (DoS) en el dispositivo afectado. La vulnerabilidad se debe a una gestión inadecuada de los recursos de socket en el código de la aplicación de respuesta IP SLA. Un atacante podría explotar esta vulnerabilidad enviando paquetes IP SLA manipulados al dispositivo afectado. Dicha explotación podría permitir al atacante bloquear la interfaz, lo que resultaría en una denegación de servicio (DoS) en el dispositivo afectado.

Consulte los BID de Cisco y el aviso de seguridad de Cisco incluidos para obtener más información.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCvf37838.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-1752', 'Vulnerabilidad de denegación de servicio en la interfaz ISDN de Cisco IOS', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que Cisco ha reportado, el software IOS de Cisco presenta una vulnerabilidad en las funciones ISDN que podría permitir a un atacante remoto no autenticado provocar el reinicio del dispositivo. Esta vulnerabilidad se debe al procesamiento incorrecto de ciertos valores en los elementos de información Q.931. Un atacante puede explotarla llamando al dispositivo afectado con la presencia de dichos elementos Q.931. De explotar esta vulnerabilidad, el atacante podría reiniciar el dispositivo, lo que resultaría en una denegación de servicio (DoS) en el mismo.

Consulte los BID de Cisco y el aviso de seguridad de Cisco incluidos para obtener más información.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en los errores de Cisco con ID CSCuz74957 y CSCvk01977.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-12665', 'Vulnerabilidad de divulgación de información del cliente HTTP de Cisco IOS (cisco-sa-20190925-http-client)', 'Alto', 5.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han reportado, iOS presenta una vulnerabilidad en la función de cliente HTTP que permite a un atacante remoto no autenticado leer y modificar datos que normalmente deberían enviarse a través de un canal cifrado. Esta vulnerabilidad se debe a que la información del puerto TCP no se tiene en cuenta al vincular nuevas solicitudes con conexiones HTTP persistentes existentes. Un atacante puede explotar esta vulnerabilidad actuando como intermediario y leyendo o modificando datos que normalmente deberían haberse transmitido a través de un canal cifrado.

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCvf36258.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-12654', 'Vulnerabilidad de denegación de servicio en Cisco IOS (cisco-sa-20190925-sip-dos)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Existe una vulnerabilidad de denegación de servicio (DoS) en el componente del Protocolo de Inicio de Sesión (SIP) de Cisco IOS debido a comprobaciones insuficientes en una estructura de datos interna que se llena con datos enviados por el usuario. Un atacante remoto no autenticado puede explotar esta vulnerabilidad para forzar el reinicio del sistema.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el ID de error de Cisco CSCvn00218.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-16009', 'Falsificación de solicitud entre sitios en la interfaz web de Cisco IOS (cisco-sa-20200108-ios-csrf)', 'Alto', 7.6, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que Cisco ha reportado, su sistema operativo IOS se ve afectado por una vulnerabilidad de falsificación de solicitud entre sitios (CSRF) en la interfaz web debido a la insuficiencia de protecciones contra CSRF. Un atacante remoto no autenticado puede explotar esta vulnerabilidad persuadiendo a un usuario de la interfaz para que siga un enlace malicioso y así realizar acciones arbitrarias con el nivel de privilegios del usuario objetivo. Si el usuario tiene privilegios de administrador, el atacante podría modificar la configuración, ejecutar comandos o reiniciar un dispositivo afectado.

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el/los ID de error de Cisco CSCvq66030 o aplique la solución alternativa mencionada en el aviso.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2020-3230', 'Ataque de denegación de servicio (DoS) de Cisco IOS Internet Key Exchange versión 2 (cisco-sa-ikev2-9p23Jj2a)', 'Alto', 5.0, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que él mismo ha informado, IOS se ve afectado por una vulnerabilidad de denegación de servicio (DoS) en su implementación de Intercambio de Claves de Internet (IKE) versión 2 debido a un manejo incorrecto de los paquetes IKEv2 SA-Init. Un atacante remoto no autenticado puede explotar este problema enviando paquetes IKEv2 SA-Init especialmente diseñados a un host afectado para provocar una denegación de servicio.

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.

Tenga en cuenta que no se ha probado este problema, sino que se ha basado únicamente en la versión autoinformada de la aplicación.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el ID de error de Cisco CSCvp44397.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2024-20307, CVE-2024-20308', 'Fragmentación de la versión 1 del intercambio de claves de Internet del software Cisco IOS (cisco-sa-ikev1-NO2ccFWz)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han publicado, Cisco IOS se ve afectado por múltiples vulnerabilidades.

Una vulnerabilidad en el código de fragmentación IKEv1 del software Cisco IOS y Cisco IOS XE podría permitir que un atacante remoto no autenticado provoque un desbordamiento de búfer, lo que resultaría en el reinicio del dispositivo afectado. Esta vulnerabilidad se debe a que los paquetes IKEv1 fragmentados y manipulados no se reensamblan correctamente. Un atacante podría explotar esta vulnerabilidad enviando paquetes UDP manipulados al sistema afectado. Una explotación exitosa podría permitir al atacante provocar el reinicio del dispositivo afectado, lo que resultaría en una denegación de servicio (DoS). Nota: Solo el tráfico dirigido al sistema afectado puede utilizarse para explotar esta vulnerabilidad. Esta vulnerabilidad puede activarse mediante tráfico IPv4 e IPv6. (CVE-2024-20307)

Una vulnerabilidad en el código de fragmentación IKEv1 del software Cisco IOS y Cisco IOS XE podría permitir que un atacante remoto no autenticado provoque un desbordamiento de búfer en el montón, lo que resultaría en el reinicio del dispositivo afectado. Esta vulnerabilidad existe porque los paquetes IKEv1 fragmentados y manipulados no se reensamblan correctamente. Un atacante podría explotar esta vulnerabilidad enviando paquetes UDP manipulados al sistema afectado. Una explotación exitosa podría permitir al atacante provocar el reinicio del dispositivo afectado, lo que resultaría en una denegación de servicio (DoS). Nota: Solo el tráfico dirigido al sistema afectado puede utilizarse para explotar esta vulnerabilidad. Esta vulnerabilidad puede activarse mediante tráfico IPv4 e IPv6.

(CVE-2024-20308)

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en los ID de error de Cisco CSCwf11183 y CSCwh66334.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2020-3511', 'Software Cisco IOS ISDN Q.931 DoS (cisco-sa-iosxe-isdn-q931-dos-67eUZBTf)', 'Alto', 6.1, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han reportado, IOS se ve afectado por una vulnerabilidad de denegación de servicio (DoS) en el subsistema ISDN debido a una validación de entrada insuficiente durante el procesamiento de los mensajes ISDN Q.931. Un atacante no autenticado y cercano podría explotar esta vulnerabilidad enviando un mensaje ISDN Q.931 malicioso a un dispositivo afectado. Si la explotación es exitosa, el atacante podría provocar el bloqueo del proceso, lo que resultaría en una denegación de servicio.

Para obtener más información, consulte el documento Cisco BID y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCvr57760.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2024-20312', 'Ataque de denegación de servicio (DoS) de sistema intermedio a sistema intermedio del software Cisco IOS (cisco-sa-isis-sGjyOUHX)', 'Alto', 6.1, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han publicado, Cisco IOS se ve afectado por una vulnerabilidad.

Una vulnerabilidad en el protocolo IS-IS (Intermediate System-to-Intermediate System) del software Cisco IOS y Cisco IOS XE podría permitir que un atacante adyacente no autenticado provoque una denegación de servicio (DoS) en un dispositivo afectado. Esta vulnerabilidad se debe a una validación de entrada insuficiente al analizar un paquete IS-IS entrante. Un atacante podría explotar esta vulnerabilidad enviando un paquete IS-IS manipulado a un dispositivo afectado tras establecer una adyacencia. Una explotación exitosa podría permitir al atacante provocar el reinicio del dispositivo afectado, lo que resultaría en una denegación de servicio (DoS). Nota: El protocolo IS-IS es un protocolo de enrutamiento. Para explotar esta vulnerabilidad, un atacante debe estar adyacente en la capa 2 al dispositivo afectado y haber establecido una adyacencia. (CVE-2024-20312)

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCwf54007.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2024-20311', 'Ataque de denegación de servicio (DoS) del protocolo de separación de identificadores de localizador de software Cisco IOS (cisco-sa-lisp-3gYXs3qP)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han publicado, Cisco IOS se ve afectado por una vulnerabilidad.

Una vulnerabilidad en el protocolo LISP (Locator ID Separation Protocol) del software Cisco IOS y Cisco IOS XE podría permitir que un atacante remoto no autenticado provoque el reinicio de un dispositivo afectado. Esta vulnerabilidad se debe a un manejo incorrecto de los paquetes LISP. Un atacante podría explotarla enviando un paquete LISP manipulado al dispositivo afectado. Si la explotación es exitosa, el atacante podría provocar el reinicio del dispositivo, lo que resultaría en una denegación de servicio (DoS). Nota: Esta vulnerabilidad podría explotarse tanto en protocolos IPv4 como IPv6. (CVE-2024-20311)

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCwf36266.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2025-20169, CVE-2025-20170, CVE-2025-20171, CVE-2025-20172, CVE-2025-20173, CVE-2025-20174, CVE-2025-20175, CVE-2025-20176', 'Software Cisco IOS SNMP DoS (cisco-sa-snmp-dos-sdxnSUcW)', 'Alto', 6.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han publicado, Cisco IOS se ve afectado por múltiples vulnerabilidades.

Una vulnerabilidad en el subsistema SNMP del software Cisco IOS y Cisco IOS XE podría permitir que un atacante remoto autenticado provoque una denegación de servicio (DoS) en un dispositivo afectado. Esta vulnerabilidad se debe a un manejo de errores inadecuado al analizar las solicitudes SNMP. Un atacante podría explotarla enviando una solicitud SNMP manipulada al dispositivo afectado. Una explotación exitosa podría permitir al atacante provocar que el dispositivo se reinicie inesperadamente, lo que resultaría en una denegación de servicio. Esta vulnerabilidad afecta a las versiones 1, 2c y 3 de SNMP. Para explotar esta vulnerabilidad mediante SNMP v2c o versiones anteriores, el atacante debe conocer una cadena de comunidad SNMP válida de lectura/escritura o solo lectura para el sistema afectado. Para explotar esta vulnerabilidad mediante SNMP v3, el atacante debe tener credenciales de usuario SNMP válidas para el sistema afectado.

(CVE-2025-20169, CVE-2025-20170, CVE-2025-20171, CVE-2025-20173, CVE-2025-20174, CVE-2025-20175, CVE-2025-20176)

Una vulnerabilidad en el subsistema SNMP del software Cisco IOS, el software Cisco IOS XE y el software Cisco IOS XR podría permitir que un atacante remoto autenticado provoque una denegación de servicio (DoS) en un dispositivo afectado.

Esta vulnerabilidad se debe a un manejo de errores inadecuado al analizar las solicitudes SNMP. Un atacante podría explotarla enviando una solicitud SNMP manipulada a un dispositivo afectado. En el caso del software Cisco IOS e IOS XE, una explotación exitosa podría permitir al atacante provocar el reinicio inesperado del dispositivo, lo que resultaría en una denegación de servicio (DoS). En el caso del software Cisco IOS XR, una explotación exitosa podría permitir al atacante provocar el reinicio del proceso SNMP, lo que resultaría en una respuesta SNMP interrumpida por parte del dispositivo afectado.

Los dispositivos que ejecutan el software Cisco IOS XR no se reiniciarán. Esta vulnerabilidad afecta a las versiones 1, 2c y 3 de SNMP. Para explotar esta vulnerabilidad mediante SNMP v2c o versiones anteriores, el atacante debe conocer una cadena de comunidad SNMP válida de lectura/escritura o solo lectura para el sistema afectado. Para explotar esta vulnerabilidad mediante SNMP v3, el atacante debe tener credenciales de usuario SNMP válidas para el sistema afectado.

(CVE-2025-20172)

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en los ID de error de Cisco CSCwm79554, CSCwm79564, CSCwm79570, CSCwm79577, CSCwm79581, CSCwm79590, CSCwm79596, CSCwm89600, CSCwn08493.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2025-20352', 'Software Cisco IOS SNMP DoS RCE (cisco-sa-snmp-x4LPhte)', 'Alto', 6.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han publicado, Cisco IOS se ve afectado por una vulnerabilidad.

Una vulnerabilidad en el subsistema del Protocolo simple de administración de red (SNMP) del software Cisco IOS y Cisco IOS XE podría permitir lo siguiente: Un atacante remoto autenticado con privilegios bajos podría provocar una denegación de servicio (DoS) en un dispositivo afectado que ejecute el software Cisco IOS o Cisco IOS XE. Para provocar la DoS, el atacante debe tener la cadena de comunidad de solo lectura SNMPv2c o anterior, o credenciales de usuario SNMPv3 válidas. Un atacante remoto autenticado con privilegios altos podría ejecutar código como usuario root en un dispositivo afectado que ejecute el software Cisco IOS XE. Para ejecutar código como usuario root, el atacante debe tener la cadena de comunidad de solo lectura SNMPv1 o v2c, o credenciales de usuario SNMPv3 válidas y credenciales administrativas o con privilegio 15 en el dispositivo afectado. Un atacante podría explotar esta vulnerabilidad enviando un paquete SNMP manipulado a un dispositivo afectado a través de redes IPv4 o IPv6. Esta vulnerabilidad se debe a una condición de desbordamiento de pila en el subsistema SNMP del software afectado. Una explotación exitosa podría permitir a un atacante con privilegios bajos provocar el reinicio del sistema afectado, resultando en una denegación de servicio (DoS), o permitir a un atacante con privilegios altos ejecutar código arbitrario como usuario root y obtener el control total del sistema afectado. Nota: Esta vulnerabilidad afecta a todas las versiones de SNMP. (CVE-2025-20352)

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCwq31287.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2020-3408', 'Ataque DoS de DNS dividido en el software Cisco IOS (cisco-sa-splitdns-SPWqpdGW)', 'Alto', 7.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la versión que ellos mismos han comunicado, el software Cisco IOS se ve afectado por una vulnerabilidad de denegación de servicio (DoS), ya que el motor de expresiones regulares (regex) de la función Split DNS puede agotar el tiempo de espera al procesar la configuración de la lista de nombres DNS.

Un atacante remoto no autenticado podría provocar que un dispositivo afectado se reinicie, lo que resultaría en una denegación de servicio.

Para obtener más información, consulte el documento Cisco BID y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCvt78186.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2022-20920', 'Software Cisco IOS SSH DoS (cisco-sa-ssh-excpt-dos-FzOBQTnk)', 'Alto', 6.8, 'Al dispositivo remoto le falta un parche de seguridad proporcionado por el fabricante.', 'Según la información proporcionada por la propia compañía, el software Cisco IOS y el software Cisco IOS XE presentan una vulnerabilidad de denegación de servicio. Un atacante remoto autenticado puede explotarla conectándose continuamente a un dispositivo afectado y enviando solicitudes SSH específicas para provocar que dicho dispositivo se reinicie.

Para obtener más información, consulte los BID de Cisco y el aviso de seguridad de Cisco que se incluyen.', 'Actualice a la versión corregida correspondiente a la que se hace referencia en el error de Cisco con ID CSCvx63027.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Detección de objetivos no autenticados iSCSI', 'Alto', 7.5, 'Al menos un destino iSCSI está configurado para no utilizar autenticación.', 'Uno o más de los destinos iSCSI (Interfaz de Sistemas de Computadoras Pequeñas de Internet) en el host remoto están configurados para no utilizar un mecanismo de autenticación, lo que podría permitir el acceso no autorizado a dichos destinos.', 'Configure la autenticación en el dispositivo de destino para restringir el acceso a los iniciadores autorizados.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Detección de objetivos no autenticados iSCSI', 'Alto', 7.5, 'Al menos un destino iSCSI está configurado para no utilizar autenticación.', 'Uno o más de los destinos iSCSI (Interfaz de Sistemas de Computadoras Pequeñas de Internet) en el host remoto están configurados para no utilizar un mecanismo de autenticación, lo que podría permitir el acceso no autorizado a dichos destinos.', 'Configure la autenticación en el dispositivo de destino para restringir el acceso a los iniciadores autorizados.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2016-2118', 'Vulnerabilidad de bloqueo de Samba', 'Alto', 6.8, 'Un servidor SMB que se ejecuta en el host remoto se ve afectado por la vulnerabilidad Badlock.', 'La versión de Samba, un servidor CIFS/SMB para Linux y Unix, que se ejecuta en el host remoto, se ve afectada por una vulnerabilidad conocida como Badlock, presente en los protocolos Security Account Manager (SAM) y Local Security Authority (Domain Policy) (LSAD) debido a una negociación incorrecta del nivel de autenticación en los canales de Remote Procedure Call (RPC). Un atacante intermediario que logre interceptar el tráfico entre un cliente y un servidor que aloja una base de datos SAM puede explotar esta vulnerabilidad para forzar una degradación del nivel de autenticación, lo que permite la ejecución de llamadas de red Samba arbitrarias en el contexto del usuario interceptado, como ver o modificar datos de seguridad confidenciales en la base de datos de Active Directory (AD) o deshabilitar servicios críticos.', 'Actualiza a la versión 4.2.11 / 4.3.8 / 4.4.2 o posterior de Samba.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2023-29552', 'ESXi < 7.0 reflejó una denegación de servicio.', 'Alto', 7.8, 'El host remoto VMware ESXi carece de un parche de seguridad y se ve afectado por una vulnerabilidad.', 'El host remoto VMware ESXi tiene una versión anterior a la 7.0 y se ve afectado por una vulnerabilidad de denegación de servicio reflejada:

El Protocolo de Localización de Servicios (SLP, RFC 2608) permite que un atacante remoto no autenticado registre servicios arbitrarios. Esto podría permitirle utilizar tráfico UDP falsificado para realizar un ataque de denegación de servicio con un factor de amplificación significativo. (CVE-2023-29552)', 'Actualice a ESXi 7.0 U2c, ESXi 8.0 GA o una versión posterior, o desactive SLP.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2021-21974', 'ESXi 6.5 / 6.7 / 7.0 RCE (VMSA-2021-0002)', 'Alto', 5.8, 'El host remoto VMware ESXi carece de un parche de seguridad y se ve afectado por una vulnerabilidad de ejecución remota de código.', 'El host VMware ESXi remoto es de la versión 6.5, 6.7 o 7.0 y está afectado por una vulnerabilidad de ejecución remota de código. OpenSLP, tal como se utiliza en ESXi (7.0 anterior a ESXi70U1c-17325551, 6.7 anterior a ESXi670-202102401-SG, 6.5 anterior a ESXi650-202102101-SG), presenta una vulnerabilidad de desbordamiento de búfer en el montón. Un atacante malicioso que se encuentre en el mismo segmento de red que ESXi y tenga acceso al puerto 427 podría provocar el desbordamiento de búfer en el servicio OpenSLP, lo que resultaría en la ejecución remota de código.', 'Aplique el parche correspondiente según se indica en el aviso del proveedor.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-11776', 'Apache Struts CVE-2018-11776 produce una ejecución remota de código sin espacio de nombres (S2-057) (remoto)', 'Alto', 9.3, 'El servidor web remoto contiene una aplicación web que utiliza un framework Java afectado por una vulnerabilidad de ejecución remota de código.', 'La versión de Apache Struts que se ejecuta en el host remoto se ve afectada por una vulnerabilidad de ejecución remota de código en el manejo de resultados sin espacio de nombres definido. Un atacante remoto no autenticado puede explotar esta vulnerabilidad, mediante una solicitud HTTP especialmente diseñada, para ejecutar potencialmente código arbitrario, sujeto a los privilegios del usuario del servidor web.', 'Actualice a la versión 2.3.35 / 2.5.17 o posterior de Apache Struts.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2013-4786', 'Divulgación del hash de contraseña de IPMI v2.0', 'Alto', 7.8, 'El host remoto admite la versión 2.0 de IPMI.', 'El host remoto admite IPMI v2.0. El protocolo de Interfaz de Gestión de Plataforma Inteligente (IPMI) se ve afectado por una vulnerabilidad de divulgación de información debido a la compatibilidad con la autenticación del Protocolo de Intercambio de Claves Autenticado (RAKP) RMCP+. Un atacante remoto puede obtener información de hash de contraseñas para cuentas de usuario válidas a través del HMAC de una respuesta de mensaje RAKP 2 de un BMC.', 'No existe un parche para esta vulnerabilidad; se trata de un problema inherente a la especificación de IPMI v2.0. Las medidas de mitigación sugeridas incluyen:', 'Procedimiento / Software', NOW());
