INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('', 'Acceso no autenticado al servidor VNC', 'Alto', 7.5, 'El servidor VNC remoto no requiere autenticación.', 'El servidor VNC instalado en el host remoto permite que un atacante se conecte a dicho host, ya que no se requiere autenticación para acceder a este servicio.

** El servidor VNC a veces envía al usuario conectado al inicio de sesión de XDM.

** pantalla. Lamentablemente,  no puede identificar esta situación.

** En tal caso, no es posible continuar sin un documento válido

** Las credenciales y esta alerta pueden ignorarse.', 'Desactive el tipo de seguridad Sin autenticación.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2026-24734', 'Apache Tomcat 9.0.83 < 9.0.115', 'Alto', 4.0, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.115. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.115_security-9.

- Vulnerabilidad de validación de entrada incorrecta en Apache Tomcat Native, Apache Tomcat. Al usar un respondedor OCSP, Tomcat Native (y el puerto FFM de Tomcat del código de Tomcat Native) no completaba las comprobaciones de verificación o vigencia en la respuesta OCSP, lo que podía permitir que se eludiera la revocación del certificado. Este problema afecta a Apache Tomcat Native: de 1.3.0 a 1.3.4, de 2.0.0 a 2.0.11; Apache Tomcat:

Desde la versión 11.0.0-M1 hasta la 11.0.17, desde la 10.1.0-M7 hasta la 10.1.51, y desde la 9.0.83 hasta la 9.0.114. Las siguientes versiones habían llegado al final de su ciclo de vida (EOL) cuando se creó la CVE, pero se sabe que están afectadas: desde la 1.1.23 hasta la 1.1.34 y desde la 1.2.0 hasta la 1.2.39. Las versiones EOL anteriores no están afectadas. Se recomienda a los usuarios de Apache Tomcat Native que actualicen a las versiones 1.3.5 o posterior, o a la 2.0.12 o posterior, que solucionan el problema. Se recomienda a los usuarios de Apache Tomcat que actualicen a las versiones 11.0.18 o posterior, 10.1.52 o posterior, o 9.0.115 o posterior, que solucionan el problema. (CVE-2026-24734)', 'Actualice a la versión 9.0.115 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-8034, CVE-2018-8037', 'Múltiples vulnerabilidades en Apache Tomcat 9.0.0.M1 < 9.0.10', 'Alto', 5.0, 'El servidor remoto Apache Tomcat se ve afectado por múltiples vulnerabilidades.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.10. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso fixed_in_apache_tomcat_9.0.10_security-9.

Faltaba la verificación del nombre de host al usar TLS con el cliente WebSocket. Ahora está habilitada por defecto. Versiones afectadas: Apache Tomcat 9.0.0.M1 a 9.0.9, 8.5.0 a 8.5.31, 8.0.0.RC1 a 8.0.52 y 7.0.35 a 7.0.88. (CVE-2018-8034)

Si la aplicación completaba una solicitud asíncrona al mismo tiempo que el contenedor activaba el tiempo de espera asíncrono, se producía una condición de carrera que podía provocar que un usuario viera una respuesta destinada a otro usuario. Además, existía un problema en los conectores NIO y NIO2 que no registraban correctamente el cierre de la conexión cuando la aplicación completaba una solicitud asíncrona y el contenedor expiraba el tiempo de espera simultáneamente. Esto también podía provocar que un usuario viera una respuesta destinada a otro usuario.

Versiones afectadas: Apache Tomcat de la versión 9.0.0.M9 a la 9.0.9 y de la 8.5.5 a la 8.5.31. (CVE-2018-8037)', 'Actualice a la versión 9.0.10 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-8034, CVE-2018-8037', 'Múltiples vulnerabilidades en Apache Tomcat 9.0.0.M1 < 9.0.10', 'Alto', 5.0, 'El servidor remoto Apache Tomcat se ve afectado por múltiples vulnerabilidades.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.10. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso fixed_in_apache_tomcat_9.0.10_security-9.

