INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2025-52434, CVE-2025-52520, CVE-2025-53506', 'Múltiples vulnerabilidades en Apache Tomcat 9.0.0.M1 < 9.0.107', 'Alto', 5.0, 'El servidor remoto Apache Tomcat se ve afectado por múltiples vulnerabilidades.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.107. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso fixed_in_apache_tomcat_9.0.107_security-9.

La vulnerabilidad se debe a un desbordamiento en el límite de carga de archivos. Un atacante remoto puede enviar solicitudes especialmente diseñadas al servidor y realizar un ataque de denegación de servicio (DoS). (CVE-2025-52520)

La vulnerabilidad se debe a una validación insuficiente de la entrada proporcionada por el usuario al procesar solicitudes HTTP/2 con APR/Native. Un atacante remoto puede enviar solicitudes HTTP especialmente diseñadas al servidor y realizar un ataque de denegación de servicio (DoS). (CVE-2025-52434)

La vulnerabilidad se debe a que la aplicación no controla adecuadamente el consumo de recursos internos al gestionar un volumen excesivo de flujos HTTP/2. Un atacante remoto puede provocar el agotamiento de los recursos y realizar un ataque de denegación de servicio (DoS). (CVE-2025-53506)', 'Actualice a la versión 9.0.107 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2025-52434, CVE-2025-52520, CVE-2025-53506', 'Múltiples vulnerabilidades en Apache Tomcat 9.0.0.M1 < 9.0.107', 'Alto', 5.0, 'El servidor remoto Apache Tomcat se ve afectado por múltiples vulnerabilidades.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.107. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se menciona en el aviso fixed_in_apache_tomcat_9.0.107_security-9.

