INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-0199', 'Apache Tomcat 9.0.0.M1 < 9.0.16', 'Alto', 5.0, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.16. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.16_security-9.

La implementación de HTTP/2 en Apache Tomcat versiones 9.0.0.M1 a 9.0.14 y 8.5.0 a 8.5.37 aceptaba flujos con un número excesivo de tramas SETTINGS y permitía a los clientes mantener los flujos abiertos sin leer ni escribir datos de solicitud/respuesta. Al mantener los flujos abiertos para solicitudes que utilizaban la E/S bloqueante de la API de Servlet, los clientes podían provocar el bloqueo de los subprocesos del servidor, lo que eventualmente conllevaba el agotamiento de los subprocesos y una denegación de servicio (DoS). (CVE-2019-0199)', 'Actualice a la versión 9.0.16 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
