INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2022-25762', 'Apache Tomcat 9.0.0.M1 < 9.0.21', 'Alto', 7.5, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.21. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.21_security-9.

Si una aplicación web envía un mensaje WebSocket simultáneamente con el cierre de la conexión WebSocket al ejecutarse en Apache Tomcat versiones 8.5.0 a 8.5.75 o Apache Tomcat versiones 9.0.0.M1 a 9.0.20, es posible que la aplicación continúe utilizando el socket después de su cierre. El manejo de errores que se activa en este caso podría provocar que un objeto del pool se coloque dos veces en él. Esto podría resultar en conexiones posteriores que utilicen el mismo objeto simultáneamente, lo que podría provocar que los datos se devuelvan al usuario incorrecto o que se produzcan otros errores. (CVE-2022-25762)', 'Actualice a la versión 9.0.21 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2022-25762', 'Apache Tomcat 9.0.0.M1 < 9.0.21', 'Alto', 7.5, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.21. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.21_security-9.

