INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-10072', 'Apache Tomcat 9.0.0.M1 < 9.0.20 DoS', 'Alto', 5.0, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.20. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.20_security-9.

La solución para la vulnerabilidad CVE-2019-0199 era incompleta y no abordaba el agotamiento de la ventana de conexión HTTP/2 durante la escritura. Al no enviar mensajes WINDOW_UPDATE para la ventana de conexión (flujo 0), los clientes podían provocar el bloqueo de los subprocesos del servidor, lo que finalmente conllevaba el agotamiento de los subprocesos y una denegación de servicio (DoS). (CVE-2019-10072)', 'Actualice a la versión 9.0.20 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-10072', 'Apache Tomcat 9.0.0.M1 < 9.0.20 DoS', 'Alto', 5.0, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.20. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.20_security-9.

