INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2019-17563', 'Apache Tomcat 9.0.0.M1 < 9.0.30', 'Alto', 5.1, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.30. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.30_security-9.

Al usar la autenticación FORM con Apache Tomcat versiones 9.0.0.M1 a 9.0.29, 8.5.0 a 8.5.49 y 7.0.0 a 7.0.98, existía un breve lapso de tiempo en el que un atacante podía realizar un ataque de fijación de sesión. Si bien se consideró que este lapso era demasiado pequeño para que un exploit resultara práctico, por precaución, este problema se ha tratado como una vulnerabilidad de seguridad. (CVE-2019-17563)', 'Actualice a la versión 9.0.30 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
