INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2020-9484', 'Apache Tomcat 9.0.0 < 9.0.35', 'Alto', 4.4, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.35. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.35_security-9.

Al usar Apache Tomcat versiones 10.0.0-M1 a 10.0.0-M4, 9.0.0.M1 a 9.0.34, 8.5.0 a 8.5.54 y 7.0.0 a 7.0.103 si a) un atacante puede controlar el contenido y el nombre de un archivo en el servidor; y b) el servidor está configurado para usar PersistenceManager con un FileStore; y c) PersistenceManager está configurado con sessionAttributeValueClassNameFilter=null (el valor predeterminado a menos que se use un SecurityManager) o un filtro suficientemente permisivo para permitir que el objeto proporcionado por el atacante se deserialice; y d) el atacante conoce la ruta de archivo relativa desde la ubicación de almacenamiento utilizada por FileStore hasta el archivo sobre el que el atacante tiene control; entonces, usando una solicitud específicamente diseñada, el atacante podrá activar la ejecución remota de código a través de la deserialización del archivo bajo su control. Tenga en cuenta que todas las condiciones de la a) a la d) deben cumplirse para que el ataque tenga éxito. (CVE-2020-9484)', 'Actualice a la versión 9.0.35 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
