INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2020-11996', 'Apache Tomcat 9.0.0.M1 < 9.0.36', 'Alto', 5.0, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.36. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.36_security-9.

Una secuencia especialmente diseñada de solicitudes HTTP/2 enviadas a Apache Tomcat (versiones 10.0.0-M1 a 10.0.0-M5, 9.0.0-M1 a 9.0.35 y 8.5.0 a 8.5.55) podría provocar un alto consumo de CPU durante varios segundos. Si se realizara un número suficiente de estas solicitudes en conexiones HTTP/2 simultáneas, el servidor podría dejar de responder.

(CVE-2020-11996)', 'Actualice a la versión 9.0.36 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
