INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2022-42252', 'Apache Tomcat 9.0.0.M1 < 9.0.68', 'Alto', 7.8, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.68. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.68_security-9.

- Si Apache Tomcat versiones 8.5.0 a 8.5.82, 9.0.0-M1 a 9.0.67, 10.0.0-M1 a 10.0.26 o 10.1.0-M1 a 10.1.0 se configuraba para ignorar encabezados HTTP no válidos estableciendo rejectIllegalHeader en falso (valor predeterminado solo para la versión 8.5.x), Tomcat no rechazaba una solicitud que contenía un encabezado Content-Length no válido, lo que posibilitaba un ataque de contrabando de solicitudes si Tomcat se encontraba detrás de un proxy inverso que tampoco rechazaba la solicitud con el encabezado no válido. (CVE-2022-42252)', 'Actualice a la versión 9.0.68 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2022-42252', 'Apache Tomcat 9.0.0.M1 < 9.0.68', 'Alto', 7.8, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.68. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.68_security-9.

