INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2023-24998', 'Apache Tomcat 9.0.0.M1 < 9.0.71', 'Alto', 7.8, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.71. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.71_security-9.

Apache Commons FileUpload, en versiones anteriores a la 1.5, no limita el número de partes de la solicitud que se procesan, lo que permite que un atacante pueda provocar una denegación de servicio (DoS) mediante una o varias cargas maliciosas. Cabe destacar que, al igual que con todos los límites de carga de archivos, la nueva opción de configuración (FileUploadBase#setFileCountMax) no está habilitada por defecto y debe configurarse explícitamente. (CVE-2023-24998)', 'Actualice a la versión 9.0.71 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2023-24998', 'Apache Tomcat 9.0.0.M1 < 9.0.71', 'Alto', 7.8, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.71. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.71_security-9.

