INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2018-1336', 'Apache Tomcat 9.0.0.M1 < 9.0.8', 'Alto', 5.0, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.8. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.8_security-9.

Un manejo inadecuado del desbordamiento en el decodificador UTF-8 con caracteres suplementarios puede provocar un bucle infinito en el decodificador, causando una denegación de servicio. Versiones afectadas: Apache Tomcat 9.0.0.M9 a 9.0.7, 8.5.0 a 8.5.30, 8.0.0.RC1 a 8.0.51 y 7.0.28 a 7.0.86. (CVE-2018-1336)', 'Actualice a la versión 9.0.8 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
