INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2024-34750', 'Apache Tomcat 9.0.0.M1 < 9.0.90', 'Alto', 5.0, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.90. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.90_security-9.

Vulnerabilidad de Apache Tomcat por manejo inadecuado de condiciones excepcionales y consumo incontrolado de recursos. Al procesar un flujo HTTP/2, Tomcat no gestionaba correctamente algunos casos de encabezados HTTP excesivos. Esto provocaba un recuento erróneo de los flujos HTTP/2 activos, lo que a su vez conllevaba el uso de un tiempo de espera infinito incorrecto, permitiendo que permanecieran abiertas conexiones que deberían haberse cerrado. Este problema afecta a Apache Tomcat: versiones 11.0.0-M1 a 11.0.0-M20, 10.1.0-M1 a 10.1.24 y 9.0.0-M1 a 9.0.89. Se recomienda a los usuarios actualizar a las versiones 11.0.0-M21, 10.1.25 o 9.0.90, que solucionan el problema. (CVE-2024-34750)', 'Actualice a la versión 9.0.90 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2024-34750', 'Apache Tomcat 9.0.0.M1 < 9.0.90', 'Alto', 5.0, 'El servidor remoto Apache Tomcat se ve afectado por una vulnerabilidad.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.90. Por lo tanto, se ve afectada por una vulnerabilidad a la que se hace referencia en el aviso fixed_in_apache_tomcat_9.0.90_security-9.

