INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2025-55752', 'Múltiples vulnerabilidades en Apache Tomcat 9.0.0.M11 < 9.0.109', 'Alto', 7.1, 'El servidor remoto Apache Tomcat se ve afectado por múltiples vulnerabilidades.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.109. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se indica en el aviso fixed_in_apache_tomcat_9.0.109_security-9.

Vulnerabilidad de recorrido de ruta relativa en Apache Tomcat. La corrección del error 60013 introdujo una regresión en la que la URL reescrita se normalizaba antes de decodificarse. Esto introdujo la posibilidad de que, para reglas de reescritura que reescriben parámetros de consulta a la URL, un atacante pudiera manipular la URI de la solicitud para eludir las restricciones de seguridad, incluida la protección para /WEB-INF/ y /META-INF/. Si también se habilitaban las solicitudes PUT, se podían cargar archivos maliciosos, lo que conducía a la ejecución remota de código. Las solicitudes PUT normalmente están limitadas a usuarios de confianza y se considera improbable que se habiliten junto con una reescritura que manipule la URI. Este problema afecta a Apache Tomcat: de 11.0.0-M1 a 11.0.10, de 10.1.0-M1 a 10.1.44, de 9.0.0.M11 a 9.0.108. Las siguientes versiones habían llegado al final de su ciclo de vida (EOL) al crearse la vulnerabilidad CVE, pero se sabe que están afectadas: de la 8.5.6 a la 8.5.100. Otras versiones anteriores, también descatalogadas, podrían verse afectadas. Se recomienda a los usuarios actualizar a la versión 11.0.11 o posterior, a la 10.1.45 o posterior, o a la 9.0.109 o posterior, que solucionan el problema. (CVE-2025-55752)', 'Actualice a la versión 9.0.109 o posterior de Apache Tomcat.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2025-55752', 'Múltiples vulnerabilidades en Apache Tomcat 9.0.0.M11 < 9.0.109', 'Alto', 7.1, 'El servidor remoto Apache Tomcat se ve afectado por múltiples vulnerabilidades.', 'La versión de Tomcat instalada en el host remoto es anterior a la 9.0.109. Por lo tanto, se ve afectada por múltiples vulnerabilidades, tal como se indica en el aviso fixed_in_apache_tomcat_9.0.109_security-9.

