INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2005-3912', 'Formato de parámetro de Webmin ''miniserv.pl'' ''username''', 'Alto', 7.5, 'El servidor web remoto se ve afectado por una vulnerabilidad en el formato de la cadena.', 'La versión de Webmin instalada en el host remoto contiene una vulnerabilidad en el formato de la cadena de registro de intentos de autenticación fallidos. Mediante valores especialmente diseñados para el parámetro ''username'' del archivo ''session_login.cgi'', un atacante podría explotar esta vulnerabilidad para bloquear el servidor afectado o ejecutar código arbitrario en el host afectado con los privilegios del usuario con el que se ejecuta el script Perl ''miniserv.pl''. El usuario predeterminado es el usuario root.', 'Actualice a la versión 1.250 o posterior de Webmin.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2012-0173', 'MS12-036: Una vulnerabilidad en Escritorio remoto podría permitir la ejecución remota de código (2685939) (verificación sin credenciales)', 'Alto', 9.3, 'El host remoto de Windows podría permitir la ejecución de código arbitrario.', 'Existe una vulnerabilidad de ejecución remota de código arbitrario en la implementación del Protocolo de Escritorio Remoto (RDP) en el host remoto de Windows. Esta vulnerabilidad se debe a la forma en que RDP accede a un objeto en memoria que ha sido inicializado o eliminado incorrectamente.

Si el protocolo RDP está habilitado en el sistema afectado, un atacante remoto no autenticado podría aprovechar esta vulnerabilidad para provocar que el sistema ejecute código arbitrario enviándole una secuencia de paquetes RDP especialmente diseñados.

Tenga en cuenta que el Protocolo de Escritorio Remoto no está habilitado de forma predeterminada.

Tenga en cuenta también que este complemento intenta provocar el fallo del sistema afectado. Solo funciona en las siguientes circunstancias:

1) El sistema remoto admite SSL para la seguridad de RDP, y 2) El sistema remoto tiene un sistema operativo de 64 bits, y 3) El servidor RDP logra asignar 4 GB de memoria paginada.', 'Microsoft ha publicado un conjunto de parches para Windows XP, 2003, Vista, 2008, 7 y 2008 R2.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2014-6321', 'MS14-066: Vulnerabilidad en Schannel que podría permitir la ejecución remota de código (2992611) (verificación sin credenciales)', 'Alto', 10.0, 'El equipo host remoto de Windows se ve afectado por una vulnerabilidad de ejecución remota de código.', 'El host remoto de Windows se ve afectado por una vulnerabilidad de ejecución remota de código debido al procesamiento incorrecto de paquetes por parte del paquete de seguridad Secure Channel (Schannel). Un atacante puede explotar esta vulnerabilidad enviando paquetes especialmente diseñados a un servidor Windows.

Tenga en cuenta que este complemento envía un mensaje de protocolo de enlace TLS para el certificado del cliente, seguido de un mensaje CertificateVerify. Algunos equipos Windows cierran la conexión al recibir un certificado de cliente no solicitado mediante un mensaje CertificateRequest. En este caso, el complemento no puede detectar la vulnerabilidad, ya que no se puede enviar el mensaje CertificateVerify.', 'Microsoft ha publicado un conjunto de parches para Windows 2003, Vista, 2008, 7, 2008 R2, 8, 2012, 8.1 y 2012 R2.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2017-0143, CVE-2017-0144, CVE-2017-0145, CVE-2017-0146, CVE-2017-0147, CVE-2017-0148', 'MS17-010: Actualización de seguridad para Microsoft Windows SMB Server (4013389) (ETERNALBLUE) (ETERNALCHAMPION) (ETERNALROMANCE) (ETERNALSYNERGY) (WannaCry) (EternalRocks) (Petya) (verificación sin credenciales)', 'Alto', 9.3, 'El host remoto de Windows se ve afectado por múltiples vulnerabilidades.', 'El host remoto de Windows se ve afectado por las siguientes vulnerabilidades:

Existen múltiples vulnerabilidades de ejecución remota de código en Microsoft Server Message Block 1.0 (SMBv1) debido a un manejo inadecuado de ciertas solicitudes. Un atacante remoto no autenticado puede explotar estas vulnerabilidades, mediante un paquete especialmente diseñado, para ejecutar código arbitrario. (CVE-2017-0143, CVE-2017-0144, CVE-2017-0145, CVE-2017-0146, CVE-2017-0148)

Existe una vulnerabilidad de divulgación de información en Microsoft Server Message Block 1.0 (SMBv1) debido a un manejo inadecuado de ciertas solicitudes. Un atacante remoto no autenticado puede explotar esta vulnerabilidad, mediante un paquete especialmente diseñado, para divulgar información confidencial. (CVE-2017-0147)

ETERNALBLUE, ETERNALCHAMPION, ETERNALROMANCE y ETERNALSYNERGY son cuatro de las múltiples vulnerabilidades y exploits del Grupo Equation revelados el 14/04/2017 por un grupo conocido como Shadow Brokers. WannaCry/WannaCrypt es un programa de ransomware que utiliza el exploit ETERNALBLUE, y EternalRocks es un gusano que utiliza siete vulnerabilidades del Grupo Equation. Petya es un programa de ransomware que primero utiliza CVE-2017-0199, una vulnerabilidad en Microsoft Office, y luego se propaga a través de ETERNALBLUE.', 'Microsoft ha publicado un conjunto de parches para Windows Vista, 2008, 7, 2008 R2, 2012, 8.1, RT 8.1, 2012 R2, 10 y 2016. Microsoft también ha publicado parches de emergencia para sistemas operativos Windows que ya no cuentan con soporte, incluidos Windows XP, 2003 y 8.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-2012-0002, CVE-2012-0152', 'MS12-020: Vulnerabilidades en Escritorio remoto podrían permitir la ejecución remota de código (2671387) (verificación sin credenciales)', 'Alto', 9.3, 'El host remoto de Windows podría permitir la ejecución de código arbitrario.', 'Existe una vulnerabilidad de código remoto arbitrario en la implementación del Protocolo de Escritorio Remoto (RDP) en el host remoto de Windows. Esta vulnerabilidad se debe a la forma en que RDP accede a un objeto en memoria que ha sido inicializado incorrectamente o que ha sido eliminado.

Si el protocolo RDP está habilitado en el sistema afectado, un atacante remoto no autenticado podría aprovechar esta vulnerabilidad para provocar que el sistema ejecute código arbitrario enviándole una secuencia de paquetes RDP especialmente diseñados.

Este complemento también comprueba si existe una vulnerabilidad de denegación de servicio en Microsoft Terminal Server.

Tenga en cuenta que este script no detecta la vulnerabilidad si la configuración "Permitir conexiones solo desde equipos que ejecutan Escritorio remoto con autenticación de nivel de red" está habilitada o si la capa de seguridad está configurada como "SSL (TLS 1.0)" en el host remoto.', 'Microsoft ha publicado un conjunto de parches para Windows XP, 2003, Vista, 2008, 7 y 2008 R2.', 'Procedimiento / Software', NOW());
INSERT INTO vulnerabilidades (cve, nombre, severidad, cvss_score, resumen, descripcion, remediacion_sugerida, recursos, fecha_registro) VALUES ('CVE-1999-0651', 'Detección de servicio rlogin', 'Alto', 7.5, 'El servicio rlogin se está ejecutando en el host remoto.', 'El servicio rlogin se ejecuta en el host remoto. Este servicio es vulnerable, ya que los datos se transmiten en texto plano entre el cliente y el servidor rlogin. Un atacante intermediario puede explotar esta vulnerabilidad para interceptar nombres de usuario y contraseñas. Además, podría permitir inicios de sesión con autenticación deficiente y sin contraseña. Si el host es vulnerable a la adivinación de números de secuencia TCP (desde cualquier red) o a la suplantación de IP (incluido el secuestro de ARP en una red local), podría ser posible eludir la autenticación.

Por último, rlogin es una forma sencilla de convertir el acceso de escritura de archivos en inicios de sesión completos a través de los archivos .rhosts o rhosts.equiv.', 'Comenta la línea ''login'' en /etc/inetd.conf y reinicia el proceso inetd. Como alternativa, desactiva este servicio y usa SSH.', 'Procedimiento / Software', NOW());
